 * デフォルト: 512KB (524,288 バイト)
 */
export const DEFAULT_MAX_FILE_SIZE_BYTES = 512 * 1024;

import { FileAnalysisInfo, ProjectAnalysisData } from '../parser/types';
import { estimateTokens } from '../parser/token-estimator';

export interface AuditPackOptions {
  maxTokens?: number; // 目標最大トークン（デフォルト 4000）
}

/**
 * 優先順位に基づいてコンテンツを制御・削ぎ落とした Audit Pack (Markdown) を生成します。
 */
export function generateAuditPack(
  data: ProjectAnalysisData,
  options: AuditPackOptions = {}
): { markdown: string; fallbackLevel: number; estimatedTokens: number } {
  const maxTokens = options.maxTokens || 4000;

  // 縮退レベル 0 から 5 まで順にシミュレーション
  for (let level = 0; level <= 5; level++) {
    const markdown = buildMarkdownForLevel(data, level);
    const tokens = estimateTokens(markdown);

    // 目標トークン数以下に収まった場合、または最終レベルに達した場合はそれを返す
    if (tokens <= maxTokens || level === 5) {
      return {
        markdown,
        fallbackLevel: level,
        estimatedTokens: tokens
      };
    }
  }

  // フォールバック（基本的にはここには来ないが、型安全のため）
  const fallbackMarkdown = buildMarkdownForLevel(data, 5);
  return {
    markdown: fallbackMarkdown,
    fallbackLevel: 5,
    estimatedTokens: estimateTokens(fallbackMarkdown)
  };
}

/**
 * 指定された縮退レベルで Markdown をビルドします。
 * 
 * レベル定義:
 * 0: フル出力 (コメント、引数型、全ファイル情報を含む)
 * 1: コメント (JSDoc/Docstring) の省略
 * 2: 詳細仕様 (引数リスト、戻り値の型) の省略、クラス名とメソッド・関数名のみ
 * 3: 優先度の低いファイル (テスト, 設定, ユーティリティ等) を Module Map / Dependencies から除外
 * 4: Module Map および Dependencies の完全省略 (主要ファイル一覧のみ)
 * 5: フォルダツリーの階層制限 (深さ2階層までに制限)
 */
function buildMarkdownForLevel(data: ProjectAnalysisData, level: number): string {
  const sections: string[] = [];

  // 1. Title & Metadata
  sections.push(`# Audit Pack - ${data.projectName}`);
  sections.push(`\nGenerated metadata:
- Date: ${new Date().toLocaleDateString()}
- Total Files: ${data.files.length}
- Target Token Limit: Optimized (Level ${level})`);

  // 2. System Overview
  sections.push('## System Overview');
  const overview = extractSystemOverview(data);
  sections.push(overview);

  // 3. Architecture
  sections.push('## Architecture');
  const architecture = inferArchitecture(data);
  sections.push(architecture);

  // 4. Folder Structure (レベル5では深さを制限)
  sections.push('## Folder Structure');
  const folderTree = limitFolderTreeDepth(data.folderStructureText, level === 5 ? 2 : 99);
  sections.push(`\`\`\`plaintext\n${folderTree}\n\`\`\``);

  // 5. Entry Points
  sections.push('## Entry Points');
  const entryPoints = findEntryPoints(data.files);
  if (entryPoints.length > 0) {
    sections.push(entryPoints.map(f => `- [${f.name}](file:///${f.path})`).join('\n'));
  } else {
    sections.push('No obvious entry points detected.');
  }

  // 6. External Libraries
  sections.push('## External Libraries');
  const extLibs = extractExternalLibraries(data.files);
  if (extLibs.length > 0) {
    sections.push(extLibs.map(lib => `- \`${lib}\``).join('\n'));
  } else {
    sections.push('No external libraries detected or listed.');
  }

  // 7. Module Map (クラス・関数定義情報。レベル4以上は省略)
  if (level < 4) {
    sections.push('## Module Map');
    const moduleMap = buildModuleMap(data.files, level);
    sections.push(moduleMap || 'No significant module definitions analyzed.');
  }

  // 8. Dependencies (ファイル間依存関係。レベル4以上は省略)
  if (level < 4) {
    sections.push('## Dependencies');
    const depsText = buildDependenciesSection(data.files, level);
    sections.push(depsText || 'No local dependency mappings found.');
  }

  // 9. Risk Areas
  sections.push('## Risk Areas');
  const risks = analyzeRiskAreas(data.files);
  if (risks.length > 0) {
    sections.push(risks.map(r => `- **[${r.file}](file:///${r.path})**: ${r.message}`).join('\n'));
  } else {
    sections.push('No significant complexity or dependency risks detected.');
  }

  // 10. Review Focus
  sections.push('## Review Focus');
  const reviewFocus = generateReviewFocus(risks);
  sections.push(reviewFocus);

  return sections.join('\n\n');
}

/**
 * プロジェクト内のドキュメント等から概要を抽出、またはフォルダ構造から簡易説明を生成
 */
function extractSystemOverview(data: ProjectAnalysisData): string {
  // README.md または PROJECT_PLAN.md などのドキュメントファイルを探す
  const docFiles = data.files.filter(f => 
    f.name.toLowerCase() === 'readme.md' || 
    f.name.toLowerCase().includes('plan') || 
    f.name.toLowerCase().includes('specification') ||
    f.name.toLowerCase().includes('仕様書')
  );

  if (docFiles.length > 0) {
    // 最も適したドキュメントファイルの冒頭部分を取得
    const bestDoc = docFiles.find(f => f.name.toLowerCase() === 'readme.md') || docFiles[0];
    if (bestDoc.content) {
      // 最初のいくつかの見出しや段落を抜き出す
      const lines = bestDoc.content.split('\n');
      const overviewLines: string[] = [];
      let headerCount = 0;

      for (const line of lines) {
        if (line.trim().startsWith('#')) {
          headerCount++;
        }
        // 見出しが3つ目に入ったら、またはある程度の文字数に達したら打ち切る
        if (headerCount > 3 || overviewLines.join('\n').length > 500) {
          break;
        }
        overviewLines.push(line);
      }
      return overviewLines.join('\n').trim() + '\n\n*(Extracted from ' + bestDoc.name + ')*';
    }
  }

  return 'This project is a TypeScript/JavaScript or Python application. Under audit verification process.';
}

/**
 * フォルダの構成からアーキテクチャ概要を推測
 */
function inferArchitecture(data: ProjectAnalysisData): string {
  const paths = data.files.map(f => f.path);
  const architectureNotes: string[] = [];

  const hasFrontend = paths.some(p => p.includes('src/components') || p.includes('src/app') || p.includes('public/'));
  const hasBackend = paths.some(p => p.includes('server/') || p.includes('api/') || p.includes('backend/'));
  const hasLib = paths.some(p => p.includes('src/lib/') || p.includes('lib/'));

  if (hasFrontend) {
    architectureNotes.push('- **Frontend**: Single Page Application (React/Vite etc.) located in `src/` directory.');
  }
  if (hasBackend) {
    architectureNotes.push('- **Backend**: Server-side modules/API endpoints located in server directories.');
  }
  if (hasLib) {
    architectureNotes.push('- **Core Logic**: Reusable domain modules, parsers or formatters located in `src/lib/` or `lib/`.');
  }

  if (architectureNotes.length === 0) {
    architectureNotes.push('- Standard codebase layout.');
  }

  return 'Based on the folder structures, the application layout includes:\n' + architectureNotes.join('\n');
}

/**
 * フォルダツリーテキストの深さを制限する
 */
function limitFolderTreeDepth(treeText: string, maxDepth: number): string {
  if (maxDepth >= 99) return treeText;

  const lines = treeText.split('\n');
  const filteredLines: string[] = [];

  for (const line of lines) {
    // アスキーアートのインデント（縦線やスペース）から深さを判定
    const match = line.match(/^([│\s]*)(├──|└──|──)/);
    if (match) {
      const prefix = match[1];
      const depth = Math.floor(prefix.length / 4) + 1;
      if (depth <= maxDepth) {
        filteredLines.push(line);
      }
    } else {
      // マッチしない行（空行やルート行など）はそのまま追加
      filteredLines.push(line);
    }
  }

  return filteredLines.join('\n');
}

/**
 * 主要なエントリーポイントファイルを検出
 */
function findEntryPoints(files: FileAnalysisInfo[]): FileAnalysisInfo[] {
  const entryKeywords = ['main.ts', 'main.tsx', 'index.ts', 'index.tsx', 'app.tsx', 'server.js', 'app.py', 'index.html'];
  return files.filter(f => entryKeywords.includes(f.name.toLowerCase()) || f.path.startsWith('src/main'));
}

/**
 * 外部ライブラリの一覧を集約
 */
function extractExternalLibraries(files: FileAnalysisInfo[]): string[] {
  const libs = new Set<string>();
  for (const file of files) {
    for (const dep of file.dependencies) {
      if (dep.isExternal) {
        libs.add(dep.importPath);
      }
    }
  }
  return Array.from(libs).sort();
}

/**
 * 優先度の低いファイル（テストや設定ファイル）を判定
 */
function isLowPriorityFile(file: FileAnalysisInfo): boolean {
  const pathLower = file.path.toLowerCase();
  return (
    pathLower.includes('__tests__') ||
    pathLower.includes('test.') ||
    pathLower.includes('.spec.') ||
    pathLower.includes('config.') ||
    pathLower.includes('constants.') ||
    pathLower.includes('setup')
  );
}

/**
 * クラス・関数の定義情報 (Module Map) を構築
 */
function buildModuleMap(files: FileAnalysisInfo[], level: number): string {
  const mapLines: string[] = [];

  for (const file of files) {
    // レベル3では、優先度の低いファイルを省略
    if (level >= 3 && isLowPriorityFile(file)) {
      continue;
    }

    if (!file.analysis) continue;
    const { classes, functions } = file.analysis;
    if (classes.length === 0 && functions.length === 0) continue;

    mapLines.push(`### [${file.path}](file:///${file.path})`);

    // クラス情報
    for (const cls of classes) {
      let clsHeader = `- **Class**: \`${cls.name}\``;
      if (cls.extends) {
        clsHeader += ` extends \`${cls.extends}\``;
      }
      mapLines.push(clsHeader);

      if (level < 1 && cls.description) {
        mapLines.push(`  > ${cls.description.replace(/\n/g, '\n  > ')}`);
      }

      for (const method of cls.methods) {
        let methodSig = `  - \`method ${method.name}`;
        if (level < 2) {
          methodSig += `(${method.arguments.join(', ')})`;
          if (method.returnType) {
            methodSig += `: ${method.returnType}`;
          }
        }
        methodSig += '`';
        mapLines.push(methodSig);

        if (level < 1 && method.description) {
          mapLines.push(`    * ${method.description.replace(/\n/g, '\n    * ')}`);
        }
      }
    }

    // 関数情報
    for (const func of functions) {
      let funcSig = `- **Function**: \`${func.name}`;
      if (level < 2) {
        funcSig += `(${func.arguments.join(', ')})`;
        if (func.returnType) {
          funcSig += `: ${func.returnType}`;
        }
      }
      funcSig += '`';
      mapLines.push(funcSig);

      if (level < 1 && func.description) {
        mapLines.push(`  > ${func.description.replace(/\n/g, '\n  > ')}`);
      }
    }
  }

  return mapLines.join('\n');
}

/**
 * 内部依存関係の記述部を構築
 */
function buildDependenciesSection(files: FileAnalysisInfo[], level: number): string {
  const depLines: string[] = [];

  for (const file of files) {
    if (level >= 3 && isLowPriorityFile(file)) {
      continue;
    }

    const localDeps = file.dependencies.filter(d => !d.isExternal && d.resolvedPath);
    if (localDeps.length === 0) continue;

    depLines.push(`- **[${file.name}](file:///${file.path})** depends on:`);
    for (const dep of localDeps) {
      depLines.push(`  - [${dep.resolvedPath}](file:///${dep.resolvedPath})`);
    }
  }

  return depLines.join('\n');
}

interface RiskInfo {
  file: string;
  path: string;
  message: string;
  severity: 'high' | 'medium' | 'low';
}

/**
 * ファイルごとの静的リスク（サイズ過大、複雑度等）を分析
 */
function analyzeRiskAreas(files: FileAnalysisInfo[]): RiskInfo[] {
  const risks: RiskInfo[] = [];

  for (const file of files) {
    // 1. サイズ過大リスク (100KB超)
    if (file.size > 100 * 1024) {
      risks.push({
        file: file.name,
        path: file.path,
        message: `File size is large (${(file.size / 1024).toFixed(1)} KB), which may impact cognitive load.`,
        severity: 'medium'
      });
    }

    if (file.analysis) {
      // 2. クラス内のメソッド数が多すぎる (15個超)
      for (const cls of file.analysis.classes) {
        if (cls.methods.length > 15) {
          risks.push({
            file: file.name,
            path: file.path,
            message: `Class \`${cls.name}\` has too many methods (${cls.methods.length}). Suggest refactoring.`,
            severity: 'medium'
          });
        }
      }

      // 3. モジュール内の定義数が多すぎる (20個超)
      const definitionCount = file.analysis.classes.length + file.analysis.functions.length;
      if (definitionCount > 20) {
        risks.push({
          file: file.name,
          path: file.path,
          message: `Module has high density of symbols (${definitionCount} classes/functions).`,
          severity: 'low'
        });
      }
    }

    // 4. 依存関係の集中 (依存先が8個超)
    const localDeps = file.dependencies.filter(d => !d.isExternal);
    if (localDeps.length > 8) {
      risks.push({
        file: file.name,
        path: file.path,
        message: `Module has high number of local dependencies (${localDeps.length}). Highly coupled.`,
        severity: 'high'
      });
    }
  }

  return risks;
}

/**
 * リスク情報からレビュー重点項目を構築
 */
function generateReviewFocus(risks: RiskInfo[]): string {
  const highRisks = risks.filter(r => r.severity === 'high');
  const medRisks = risks.filter(r => r.severity === 'medium');

  const focusPoints: string[] = [];

  if (highRisks.length > 0) {
    focusPoints.push(`1. **Highly Coupled Modules**: Focus on architectural boundary decoupling, specifically for modules with high dependencies like ${highRisks.map(r => `\`${r.file}\``).slice(0, 3).join(', ')}.`);
  }
  if (medRisks.length > 0) {
    focusPoints.push(`2. **Large File Sizes / Class complexity**: Verify if large classes or files (${medRisks.map(r => `\`${r.file}\``).slice(0, 3).join(', ')}) can be split or simplified.`);
  }

  focusPoints.push('3. **API Integrity & Typings**: Verify interface boundaries, parameters, and error handling for main entry points.');
  focusPoints.push('4. **Security & Data Isolation**: Review that no hardcoded credentials or unwanted external requests exist.');

  return focusPoints.join('\n');
}

import { ProjectAnalysisData, FileAnalysisInfo } from '../parser/types';
import { estimateTokens } from '../parser/token-estimator';

export interface DeepAuditPackOptions {
  maxTokens?: number; // 目標最大トークン（デフォルト 4000）
}

/**
 * 特定のファイル（モジュール）に焦点を当てた詳細な監査パック（Markdown）を生成します。
 * 目標トークン数に収まるよう、必要に応じて自動的に縮退レベルを切り替えます。
 */
export function generateDeepAuditPack(
  data: ProjectAnalysisData,
  targetFilePath: string,
  options: DeepAuditPackOptions = {}
): { markdown: string; fallbackLevel: number; estimatedTokens: number } {
  const maxTokens = options.maxTokens || 4000;

  // 縮退レベル 0 から 5 まで順にシミュレーション
  for (let level = 0; level <= 5; level++) {
    const markdown = buildMarkdownForLevel(data, targetFilePath, level);
    const tokens = estimateTokens(markdown);

    // 目標トークン数以下に収まった場合、または最終レベルに達した場合はそれを返す
    if (tokens <= maxTokens || level === 5) {
      return {
        markdown,
        fallbackLevel: level,
        estimatedTokens: tokens
      };
    }
  }

  // フォールバック（基本的にはここには来ないが、型安全のため）
  const fallbackMarkdown = buildMarkdownForLevel(data, targetFilePath, 5);
  return {
    markdown: fallbackMarkdown,
    fallbackLevel: 5,
    estimatedTokens: estimateTokens(fallbackMarkdown)
  };
}

/**
 * 指定された縮退レベルで Markdown をビルドします。
 * 
 * レベル定義:
 * 0: フル出力 (ソースコード全文、コメント、関連ファイル、詳細仕様を含む)
 * 1: ソースコード内のコメント (JSDoc/Docstring/インラインコメント) の除去、説明文の省略
 * 2: ソースコードを「スケルトン（定義のみ、実装部省略）」に置換
 * 3: 関連ファイル (Related Files) および 依存関係 (Dependencies) セクションを省略
 * 4: クラス・関数の詳細定義（引数リストや戻り値の型）を省略し、名前のみにする
 * 5: コードブロック (Code Summary) を完全に省略
 */
function buildMarkdownForLevel(
  data: ProjectAnalysisData,
  targetFilePath: string,
  level: number
): string {
  const file = data.files.find(f => f.path === targetFilePath);
  if (!file) {
    return `# Deep Audit Pack - File Not Found\n\nSpecified file \`${targetFilePath}\` could not be found in the project analysis data.`;
  }

  const sections: string[] = [];
  const dotIndex = file.name.lastIndexOf('.');
  const ext = dotIndex !== -1 ? file.name.substring(dotIndex).toLowerCase() : '';
  const isPython = ext === '.py';

  // 1. Title
  sections.push(`# Deep Audit Pack - ${file.name}`);

  // 2. Module Name
  sections.push('## Module Name');
  sections.push(`- **Path**: [${file.path}](file:///${file.path})
- **Size**: ${(file.size / 1024).toFixed(2)} KB
- **Language**: ${isPython ? 'Python' : 'JavaScript/TypeScript'}
- **Tokens (Raw File)**: ${file.tokens}
- **Optimized Level**: Level ${level}`);

  // 3. Purpose
  sections.push('## Purpose');
  if (level < 1) {
    const purpose = extractPurpose(file);
    sections.push(purpose);
  } else {
    sections.push('Detailed purpose omitted due to optimization level.');
  }

  // 4. Related Files (レベル3以上は省略)
  if (level < 3) {
    sections.push('## Related Files');
    const related = findRelatedFiles(data, targetFilePath);
    if (related.importedBy.length > 0 || related.dependsOn.length > 0) {
      const relLines: string[] = [];
      if (related.importedBy.length > 0) {
        relLines.push('**Imported by**:');
        related.importedBy.forEach(path => relLines.push(`- [${path}](file:///${path})`));
      }
      if (related.dependsOn.length > 0) {
        if (relLines.length > 0) relLines.push('');
        relLines.push('**Depends on**:');
        related.dependsOn.forEach(path => relLines.push(`- [${path}](file:///${path})`));
      }
      sections.push(relLines.join('\n'));
    } else {
      sections.push('No local related files detected.');
    }
  }

  // 5. Dependencies (レベル3以上は省略)
  if (level < 3) {
    sections.push('## Dependencies');
    const extLibs = file.dependencies.filter(d => d.isExternal).map(d => d.importPath);
    const localDeps = file.dependencies.filter(d => !d.isExternal && d.resolvedPath).map(d => d.resolvedPath!);

    const depLines: string[] = [];
    if (extLibs.length > 0) {
      depLines.push('**External Libraries**:');
      extLibs.forEach(lib => depLines.push(`- \`${lib}\``));
    }
    if (localDeps.length > 0) {
      if (depLines.length > 0) depLines.push('');
      depLines.push('**Local Imports**:');
      localDeps.forEach(path => depLines.push(`- [${path}](file:///${path})`));
    }

    if (depLines.length === 0) {
      sections.push('No import dependencies detected.');
    } else {
      sections.push(depLines.join('\n'));
    }
  }

  // 6. Public APIs
  sections.push('## Public APIs');
  const publicApis = buildPublicApisList(file);
  sections.push(publicApis || 'No public exports detected.');

  // 7. Classes
  sections.push('## Classes');
  const classesText = buildClassesSection(file, level);
  sections.push(classesText || 'No classes defined in this module.');

  // 8. Functions
  sections.push('## Functions');
  const functionsText = buildFunctionsSection(file, level);
  sections.push(functionsText || 'No module-level functions defined.');

  // 9. Data Flow
  sections.push('## Data Flow');
  const dataFlow = inferDataFlow(file);
  sections.push(dataFlow);

  // 10. Code Summary (レベル5は省略)
  if (level < 5) {
    sections.push('## Code Summary');
    const codeBlockLang = isPython ? 'python' : (ext === '.tsx' ? 'tsx' : 'typescript');
    let codeContent = '';

    if (level === 0) {
      codeContent = file.content || '// No source content available';
    } else if (level === 1) {
      codeContent = cleanCodeComments(file.content || '', ext);
    } else {
      // レベル 2, 3, 4 ではスケルトンコードを表示
      codeContent = buildSkeletonCode(file, ext, level);
    }

    sections.push(`\`\`\`${codeBlockLang}\n${codeContent}\n\`\`\``);
  }

  // 11. Potential Risks
  sections.push('## Potential Risks');
  const risks = analyzePotentialRisks(file);
  if (risks.length > 0) {
    sections.push(risks.map(r => `- **${r.type}**: ${r.message}`).join('\n'));
  } else {
    sections.push('No significant local risks detected.');
  }

  return sections.join('\n\n');
}

/**
 * モジュールの最初の説明またはJSDocからPurpose（目的）を抽出
 */
function extractPurpose(file: FileAnalysisInfo): string {
  if (file.analysis) {
    // 最初に見つかったクラスまたは関数の説明文を流用
    for (const cls of file.analysis.classes) {
      if (cls.description) return cls.description;
    }
    for (const func of file.analysis.functions) {
      if (func.description) return func.description;
    }
  }

  // ファイル冒頭のコメントを簡易抽出
  if (file.content) {
    const lines = file.content.split('\n').slice(0, 10);
    const firstComments: string[] = [];
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/**')) {
        firstComments.push(trimmed.replace(/^\/\/|^\/\*\*|^\*|\*\/$/g, '').trim());
      } else if (trimmed.startsWith('#')) {
        firstComments.push(trimmed.replace(/^#/g, '').trim());
      } else if (trimmed.startsWith('"""') || trimmed.startsWith("'''")) {
        // Python トリプルクォート開始
        firstComments.push(trimmed.replace(/^"""|^'''/g, '').trim());
      } else if (trimmed !== '') {
        // コメント以外が出現したら打ち切る
        break;
      }
    }
    const cleanComments = firstComments.filter(c => c.length > 0);
    if (cleanComments.length > 0) {
      return cleanComments.join('\n');
    }
  }

  return `This module provides functionality related to \`${file.name}\`.`;
}

/**
 * 関連するローカルファイル（依存先、被依存元）を特定
 */
interface RelatedFilesInfo {
  dependsOn: string[];
  importedBy: string[];
}

function findRelatedFiles(data: ProjectAnalysisData, targetFilePath: string): RelatedFilesInfo {
  const dependsOn: string[] = [];
  const importedBy: string[] = [];

  const targetFile = data.files.find(f => f.path === targetFilePath);
  if (targetFile) {
    // 依存しているファイル
    targetFile.dependencies.forEach(dep => {
      if (!dep.isExternal && dep.resolvedPath) {
        dependsOn.push(dep.resolvedPath);
      }
    });
  }

  // 依存されているファイル（インポート元）
  data.files.forEach(file => {
    if (file.path === targetFilePath) return;
    const isImported = file.dependencies.some(dep => 
      !dep.isExternal && dep.resolvedPath === targetFilePath
    );
    if (isImported) {
      importedBy.push(file.path);
    }
  });

  return {
    dependsOn: Array.from(new Set(dependsOn)).sort(),
    importedBy: Array.from(new Set(importedBy)).sort()
  };
}

/**
 * 公開APIの概要一覧を構築
 */
function buildPublicApisList(file: FileAnalysisInfo): string {
  if (!file.analysis) return '';
  const apis: string[] = [];

  const { classes, functions, exports } = file.analysis;

  // エクスポート宣言されたクラスと関数
  classes.forEach(cls => {
    if (cls.isExported || exports.includes(cls.name)) {
      apis.push(`- **Class**: \`${cls.name}\``);
    }
  });

  functions.forEach(func => {
    if (func.isExported || exports.includes(func.name)) {
      apis.push(`- **Function**: \`${func.name}\``);
    }
  });

  return apis.join('\n');
}

/**
 * Classesセクションをビルド
 */
function buildClassesSection(file: FileAnalysisInfo, level: number): string {
  if (!file.analysis || file.analysis.classes.length === 0) return '';
  const lines: string[] = [];

  for (const cls of file.analysis.classes) {
    let clsHeader = `### Class: \`${cls.name}\``;
    if (cls.extends) {
      clsHeader += ` extends \`${cls.extends}\``;
    }
    lines.push(clsHeader);

    if (level < 1 && cls.description) {
      lines.push(`> ${cls.description.replace(/\n/g, '\n> ')}`);
    }

    if (cls.methods.length > 0) {
      lines.push('\n**Methods**:');
      for (const method of cls.methods) {
        let methodSig = `- \`${method.name}`;
        if (level < 4) {
          methodSig += `(${method.arguments.join(', ')})`;
          if (method.returnType) {
            methodSig += `: ${method.returnType}`;
          }
        }
        methodSig += '\`';
        lines.push(methodSig);

        if (level < 1 && method.description) {
          lines.push(`  > ${method.description.replace(/\n/g, '\n  > ')}`);
        }
      }
    }
    lines.push(''); // クラス間スペース
  }

  return lines.join('\n').trim();
}

/**
 * Functionsセクションをビルド
 */
function buildFunctionsSection(file: FileAnalysisInfo, level: number): string {
  if (!file.analysis || file.analysis.functions.length === 0) return '';
  const lines: string[] = [];

  for (const func of file.analysis.functions) {
    let funcSig = `### Function: \`${func.name}`;
    if (level < 4) {
      funcSig += `(${func.arguments.join(', ')})`;
      if (func.returnType) {
        funcSig += `: ${func.returnType}`;
      }
    }
    funcSig += '\`';
    lines.push(funcSig);

    if (level < 1 && func.description) {
      lines.push(`> ${func.description.replace(/\n/g, '\n> ')}`);
    }
    lines.push('');
  }

  return lines.join('\n').trim();
}

/**
 * 入出力からデータフローを推測
 */
function inferDataFlow(file: FileAnalysisInfo): string {
  const inputs: string[] = [];
  const outputs: string[] = [];

  // 入力：ローカルインポートなど
  file.dependencies.forEach(dep => {
    if (!dep.isExternal && dep.resolvedPath) {
      const name = dep.resolvedPath.split('/').pop() || dep.importPath;
      inputs.push(`\`${name}\` (local module)`);
    } else if (dep.isExternal) {
      inputs.push(`\`${dep.importPath}\` (external package)`);
    }
  });

  // 出力：公開API
  if (file.analysis) {
    file.analysis.exports.forEach(exp => {
      outputs.push(`\`${exp}\``);
    });
  }

  const inText = inputs.length > 0 ? inputs.join(', ') : 'No special inputs (pure library/entry point)';
  const outText = outputs.length > 0 ? outputs.join(', ') : 'No public exports (executes internally)';

  return `1. **Inputs (Dependencies)**: Imports symbols from ${inText}.
2. **Internal Processing**: Exposes classes or functions for execution.
3. **Outputs (API Boundaries)**: Exports ${outText} to parent/imported modules.`;
}

/**
 * コメントやDocstringをコードから除去
 */
function cleanCodeComments(content: string, ext: string): string {
  const isPython = ext.toLowerCase() === '.py';
  if (isPython) {
    // 1. # コメントの除去
    let cleaned = content.replace(/#.*/g, '');
    // 2. トリプルクォートDocstringの除去
    cleaned = cleaned.replace(/"""[\s\S]*?"""/g, '');
    cleaned = cleaned.replace(/'''[\s\S]*?'''/g, '');
    // 3. 空行の整理
    return cleaned
      .split('\n')
      .map(line => line.trimEnd())
      .filter((line, idx, arr) => line !== '' || (idx > 0 && arr[idx - 1] !== ''))
      .join('\n')
      .trim();
  } else {
    // JS/TS
    // 1. 複数行コメントの除去
    let cleaned = content.replace(/\/\*[\s\S]*?\*\//g, '');
    // 2. 行コメントの除去
    cleaned = cleaned.replace(/(^|[^:])\/\/.*/g, '$1');
    // 3. 空行の整理
    return cleaned
      .split('\n')
      .map(line => line.trimEnd())
      .filter((line, idx, arr) => line !== '' || (idx > 0 && arr[idx - 1] !== ''))
      .join('\n')
      .trim();
  }
}

/**
 * クラス・関数定義データからスケルトンコードを再生成する
 */
function buildSkeletonCode(file: FileAnalysisInfo, ext: string, level: number): string {
  if (!file.analysis) return '// No module analysis structure available to generate skeleton.';

  const lines: string[] = [];
  const isPython = ext.toLowerCase() === '.py';

  if (isPython) {
    for (const cls of file.analysis.classes) {
      let clsLine = `class ${cls.name}`;
      if (cls.extends) {
        clsLine += `(${cls.extends})`;
      }
      clsLine += ':';
      lines.push(clsLine);

      if (cls.methods.length === 0) {
        lines.push('    pass');
      } else {
        for (const method of cls.methods) {
          let args = '';
          if (level < 4) {
            args = ['self', ...method.arguments].join(', ');
          } else {
            args = '...';
          }
          let methodLine = `    def ${method.name}(${args})`;
          if (level < 4 && method.returnType) {
            methodLine += ` -> ${method.returnType}`;
          }
          methodLine += ':';
          lines.push(methodLine);
          lines.push('        pass');
        }
      }
      lines.push(''); // 空行
    }

    for (const func of file.analysis.functions) {
      let args = '';
      if (level < 4) {
        args = func.arguments.join(', ');
      } else {
        args = '...';
      }
      let funcLine = `def ${func.name}(${args})`;
      if (level < 4 && func.returnType) {
        funcLine += ` -> ${func.returnType}`;
      }
      funcLine += ':';
      lines.push(funcLine);
      lines.push('    pass');
      lines.push('');
    }
  } else {
    for (const cls of file.analysis.classes) {
      const exportPrefix = cls.isExported ? 'export ' : '';
      let clsLine = `${exportPrefix}class ${cls.name}`;
      if (cls.extends) {
        clsLine += ` extends ${cls.extends}`;
      }
      clsLine += ' {';
      lines.push(clsLine);

      for (const method of cls.methods) {
        let args = '';
        if (level < 4) {
          args = method.arguments.join(', ');
        } else {
          args = '...';
        }
        let methodLine = `  ${method.name}(${args})`;
        if (level < 4 && method.returnType) {
          methodLine += `: ${method.returnType}`;
        }
        methodLine += ';';
        lines.push(methodLine);
      }
      lines.push('}');
      lines.push('');
    }

    for (const func of file.analysis.functions) {
      const exportPrefix = func.isExported ? 'export ' : '';
      let args = '';
      if (level < 4) {
        args = func.arguments.join(', ');
      } else {
        args = '...';
      }
      let funcLine = `${exportPrefix}function ${func.name}(${args})`;
      if (level < 4 && func.returnType) {
        funcLine += `: ${func.returnType}`;
      }
      funcLine += ';';
      lines.push(funcLine);
      lines.push('');
    }
  }

  return lines.join('\n').trim();
}

interface RiskInfo {
  type: string;
  message: string;
}

/**
 * モジュール固有のリスク領域を分析
 */
function analyzePotentialRisks(file: FileAnalysisInfo): RiskInfo[] {
  const risks: RiskInfo[] = [];

  // 1. サイズ過大
  if (file.size > 20 * 1024) {
    risks.push({
      type: 'Large File Size',
      message: `File size is ${(file.size / 1024).toFixed(1)} KB. Suggest extracting core logic to sub-modules.`
    });
  }

  // 2. 結合度（ローカル依存関係数）
  const localDeps = file.dependencies.filter(d => !d.isExternal);
  if (localDeps.length > 5) {
    risks.push({
      type: 'High Coupling',
      message: `Module has ${localDeps.length} local dependencies. High coupling increases regression risks.`
    });
  }

  // 3. クラス内のメソッド過大
  if (file.analysis) {
    for (const cls of file.analysis.classes) {
      if (cls.methods.length > 10) {
        risks.push({
          type: 'Complex Class',
          message: `Class \`${cls.name}\` has ${cls.methods.length} methods. High cognitive load.`
        });
      }
    }
  }

  return risks;
}

import { ProjectAnalysisData } from '../parser/types';
import { estimateTokens } from '../parser/token-estimator';

export interface DocPackOptions {
  maxTokens?: number; // 目標最大トークン数（デフォルト 4000）
}

/**
 * プロジェクト仕様書や紹介・まとめ記事の自動生成を目的として、
 * プロジェクトの概要、目的、背景、アーキテクチャ、機能一覧、技術ハイライト、導入メリット、将来計画をまとめる
 * Project Documentation Pack (Markdown) を生成します。
 * 目標トークン数に収まるよう、必要に応じて自動的に縮退レベルを切り替えます。
 */
export function generateDocPack(
  data: ProjectAnalysisData,
  options: DocPackOptions = {}
): { markdown: string; fallbackLevel: number; estimatedTokens: number } {
  const maxTokens = options.maxTokens || 4000;

  // 縮退レベル 0 から 5 まで順にシミュレーション
  for (let level = 0; level <= 5; level++) {
    const markdown = buildMarkdownForLevel(data, level);
    const tokens = estimateTokens(markdown);

    // 目標トークン数以下に収まった場合、または最終レベルに達した場合はそれを返す
    if (tokens <= maxTokens || level === 5) {
      return {
        markdown,
        fallbackLevel: level,
        estimatedTokens: tokens
      };
    }
  }

  // フォールバック
  const fallbackMarkdown = buildMarkdownForLevel(data, 5);
  return {
    markdown: fallbackMarkdown,
    fallbackLevel: 5,
    estimatedTokens: estimateTokens(fallbackMarkdown)
  };
}

/**
 * 指定された縮退レベルで Markdown をビルドします。
 * 
 * レベル定義:
 * 0: フル出力 (各セクションを詳細に出力、制限なし)
 * 1: Technical Highlights (技術選定や決定事項) を最大5件に制限
 * 2: Main Features の説明文を省略し、機能名のみのリストに簡略化
 * 3: Overview および Background の詳細説明を最大200文字に制限
 * 4: Future Plans セクションを省略（または最大3件に制限）
 * 5: Architecture を最小限の構成表記のみにし、Benefits セクションを完全省略
 */
function buildMarkdownForLevel(data: ProjectAnalysisData, level: number): string {
  const sections: string[] = [];

  // 1. Title
  sections.push('# Project Documentation');

  // 2. Overview
  sections.push('## Overview');
  const overview = extractOverview(data, level);
  sections.push(overview);

  // 3. Purpose
  sections.push('## Purpose');
  const purpose = extractPurpose(data);
  sections.push(purpose);

  // 4. Background
  sections.push('## Background');
  const background = extractBackground(data, level);
  sections.push(background);

  // 5. Architecture
  sections.push('## Architecture');
  const architecture = inferArchitecture(data, level);
  sections.push(architecture);

  // 6. Main Features
  sections.push('## Main Features');
  const features = extractFeatures(data, level);
  sections.push(features.map(f => `- ${f}`).join('\n'));

  // 7. Technical Highlights
  sections.push('## Technical Highlights');
  const highlights = extractTechnicalHighlights(data);
  if (level >= 1 && highlights.length > 5) {
    const subset = highlights.slice(0, 5);
    sections.push(subset.map(h => `- ${h}`).join('\n') + `\n- (Additional technical highlights omitted)`);
  } else {
    sections.push(highlights.map(h => `- ${h}`).join('\n'));
  }

  // 8. Benefits
  if (level < 5) {
    sections.push('## Benefits');
    const benefits = extractBenefits(data);
    sections.push(benefits.map(b => `- ${b}`).join('\n'));
  }

  // 9. Future Plans
  if (level < 4) {
    sections.push('## Future Plans');
    const plans = extractFuturePlans(data);
    sections.push(plans.map(p => `- ${p}`).join('\n'));
  } else if (level === 4) {
    const plans = extractFuturePlans(data);
    if (plans.length > 3) {
      sections.push('## Future Plans');
      const subset = plans.slice(0, 3);
      sections.push(subset.map(p => `- ${p}`).join('\n') + `\n- ...and ${plans.length - 3} more planned action(s) omitted.`);
    } else {
      sections.push('## Future Plans');
      sections.push(plans.map(p => `- ${p}`).join('\n'));
    }
  }

  return sections.join('\n\n');
}

/**
 * プロジェクト概要の抽出
 */
function extractOverview(data: ProjectAnalysisData, level: number): string {
  const baseMeta = `Project Name: ${data.projectName}
Scale: ${data.files.length} files (${(data.totalBytes / 1024).toFixed(1)} KB)`;

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  const readmeFile = data.files.find(f => f.name.toLowerCase() === 'readme.md');
  const sourceFile = planFile || readmeFile;

  if (sourceFile && sourceFile.content) {
    const lines = sourceFile.content.split('\n');
    let foundHeader = false;
    const descLines: string[] = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('#') && !trimmed.startsWith('##')) {
        foundHeader = true;
        continue;
      }
      if (foundHeader) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed !== '') {
          descLines.push(trimmed);
        }
      }
    }
    if (descLines.length > 0) {
      const desc = descLines.join(' ');
      if (level >= 3) {
        const truncatedDesc = desc.length > 200 ? desc.substring(0, 197) + '...' : desc;
        return `${baseMeta}\nSummary: ${truncatedDesc}`;
      } else {
        const truncatedDesc = desc.length > 500 ? desc.substring(0, 497) + '...' : desc;
        return `${baseMeta}\nSummary: ${truncatedDesc}`;
      }
    }
  }

  return `${baseMeta}\nSummary: A client-side static web utility for scanning directories and compiling LLM-friendly developer contexts without data leaks.`;
}

/**
 * 開発目的の抽出
 */
function extractPurpose(data: ProjectAnalysisData): string {
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    let inSection = false;
    const purposeLines: string[] = [];
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('##') && (trimmed.includes('目的') || trimmed.includes('ゴール') || trimmed.includes('Purpose') || trimmed.includes('Goal'))) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed !== '') {
          purposeLines.push(trimmed);
        }
      }
    }
    if (purposeLines.length > 0) {
      return purposeLines.join('\n');
    }
  }

  return `The core purpose of this project is to optimize the AI development workflow by parsing raw workspace folder structures, analyzing module interfaces (classes, methods, dependencies), and composing highly structured, compressed context packages for LLMs to reduce token consumption and manual overhead.`;
}

/**
 * 開発背景の抽出
 */
function extractBackground(data: ProjectAnalysisData, level: number): string {
  const defaultBg = `As AI-driven development scales, modern source trees grow larger, causing "context bloat" and token overflow in LLMs. Developers face immense difficulty transferring complex project progress, architectural decisions, and current constraints across different chat sessions or distinct LLM models.`;

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    let inSection = false;
    const bgLines: string[] = [];
    for (const line of lines) {
      const trimmed = line.trim();
      // 背景に関連するセクションを探索
      if (trimmed.startsWith('##') && (trimmed.includes('背景') || trimmed.includes('課題') || trimmed.includes('Background') || trimmed.includes('Overview'))) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed !== '' && !trimmed.startsWith('* **')) { // メタデータを除外
          bgLines.push(trimmed);
        }
      }
    }
    if (bgLines.length > 0) {
      const text = bgLines.join(' ');
      if (level >= 3) {
        return text.length > 200 ? text.substring(0, 197) + '...' : text;
      }
      return text.length > 500 ? text.substring(0, 497) + '...' : text;
    }
  }

  if (level >= 3) {
    return defaultBg.length > 200 ? defaultBg.substring(0, 197) + '...' : defaultBg;
  }
  return defaultBg;
}

/**
 * アーキテクチャ構成
 */
function inferArchitecture(data: ProjectAnalysisData, level: number): string {
  if (level >= 5) {
    return 'Client-side web application leveraging standard File System Access API for local, memory-only project static analysis.';
  }

  const paths = data.files.map(f => f.path);
  const notes: string[] = [];

  const hasComponents = paths.some(p => p.includes('src/components'));
  const hasApp = paths.some(p => p.includes('src/app'));
  const hasLib = paths.some(p => p.includes('src/lib'));
  const hasParser = paths.some(p => p.includes('src/lib/parser'));
  const hasFormatters = paths.some(p => p.includes('src/lib/formatters'));

  notes.push('- **Platform**: Client-side execution context built on Vite + React + TypeScript + TailwindCSS.');
  notes.push('- **Security**: Zero remote network APIs involved. Processing occurs entirely in browser memory.');

  if (hasApp) {
    notes.push('- **App Entry**: Main control flows and reactive state management (`src/app/`).');
  }
  if (hasComponents) {
    notes.push('- **UI Layer**: Reusable components representing directory pickers, file viewers, and status indicators (`src/components/`).');
  }
  if (hasLib) {
    notes.push('- **Core Library**: Reusable core utilities and formatters located under `src/lib/`.');
  }
  if (hasParser) {
    notes.push('- **Analysis Engines**: Module parsing, dependency path resolution, and token weight estimates (`src/lib/parser/`).');
  }
  if (hasFormatters) {
    notes.push('- **Formatters**: Layout configurations for specialized LLM context prompts (`src/lib/formatters/`).');
  }

  return 'The application features a modular static architecture designed for rapid client-side file reading:\n' + notes.join('\n');
}

/**
 * 主要機能の抽出
 */
function extractFeatures(data: ProjectAnalysisData, level: number): string[] {
  const features: string[] = [];
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');

  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      const tableMatch = line.match(/\|\s*\*\*(Phase\s*\d+)\*\*\s*\|\s*([^|]+)\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        const phaseName = tableMatch[1].trim();
        const statusText = tableMatch[2].trim();
        const taskContent = tableMatch[3].trim();

        if (level >= 2) {
          features.push(`${phaseName}: ${taskContent.split('（')[0].split('(')[0].trim()}`);
        } else {
          features.push(`${phaseName} [${statusText}]: ${taskContent}`);
        }
      }
    }
  }

  if (features.length > 0) {
    return features;
  }

  return [
    'Directory Tree Scanning: Generate interactive directory lists based on customizable exclusion configurations.',
    'Module Parsing: Static regex analysis for classes, methods, imports, and variables across JS/TS/Python source files.',
    'Dependency Mapping: Path resolution mapping to identify modular relationships and external requirements.',
    'Context Compression: Configurable token constraints using weight scaling to prevent model context limits.',
    'Multi-Pack Exporters: Custom prompt builders tailored for Chat Handover, Deep Audit, and Transfer Pack templates.'
  ];
}

/**
 * 技術ハイライトの抽出
 */
function extractTechnicalHighlights(data: ProjectAnalysisData): string[] {
  const highlights: string[] = [];
  const recordFile = data.files.find(f => f.name.toLowerCase() === 'record.md');
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  const targetFile = recordFile || planFile;

  if (targetFile && targetFile.content) {
    const lines = targetFile.content.split('\n');
    let inSection = false;
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('##') && (
        trimmed.includes('技術決定') || 
        trimmed.includes('設計判断') || 
        trimmed.includes('意思決定') || 
        trimmed.includes('技術選定') || 
        trimmed.includes('Decision') || 
        trimmed.includes('成功条件') || 
        trimmed.includes('防衛方針')
      )) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          const text = trimmed.replace(/^[-*]\s*(\[[ xX/]+\])?\s*/, '').trim();
          if (text) highlights.push(text);
        }
      }
    }
  }

  const uniqueHighlights = Array.from(new Set(highlights));
  if (uniqueHighlights.length > 0) {
    return uniqueHighlights;
  }

  return [
    'Secure offline client-side only processing (no network transmission).',
    'Vite + React + TypeScript + TailwindCSS codebase configuration.',
    'File System Access API (showDirectoryPicker) for loading outside directories in Chrome/Edge.',
    'Tokenizer estimation weighing English/Japanese ratios dynamically.',
    '6-stage progressive information shrinkage logic per pack type.'
  ];
}

/**
 * 導入メリット
 */
function extractBenefits(data: ProjectAnalysisData): string[] {
  return [
    `Zero Information Leakage: Full offline processing guarantees that "${data.projectName}" source files are never transmitted to external APIs.`,
    'Reduced Token Overhead: Smart context compression filters out comments, modules, and duplicate structures, saving up to 80% in token usage.',
    'Seamless LLM Continuity: Facilitates fast chat transition by consolidating tasks, decisions, and progress in unified copyable templates.',
    'High Portability: Lightweight, single-page bundle executes instantly on standard web browsers with a single shell launcher.'
  ];
}

/**
 * 将来の計画
 */
function extractFuturePlans(data: ProjectAnalysisData): string[] {
  const plans: string[] = [];
  const taskFile = data.files.find(f => f.name.toLowerCase() === 'task.md');

  if (taskFile && taskFile.content) {
    const lines = taskFile.content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('-') && trimmed.includes('[ ]')) {
        const text = trimmed.replace(/^-\s*\[\s*\]\s*/, '').trim();
        if (text) plans.push(text);
      }
    }
  }

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      const tableMatch = line.match(/\|\s*\*\*(Phase\s*\d+)\*\*\s*\|\s*`\[\s*\]`\s*未着手\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        plans.push(`Phase Pending: ${tableMatch[2].trim()}`);
      }
    }
  }

  const uniquePlans = Array.from(new Set(plans));
  return uniquePlans.length > 0 ? uniquePlans : ['Implementation of Phase Summary formatter.', 'Integrate regression test scenarios.', 'Final builds distribution.'];
}

import { ProjectAnalysisData } from '../parser/types';
import { estimateTokens } from '../parser/token-estimator';

export interface HandoverPackOptions {
  maxTokens?: number; // 目標最大トークン数（デフォルト 4000）
}

/**
 * プロジェクト解析データから進捗・成果物・制約などをまとめる Handover パック (Markdown) を生成します。
 * 目標トークン数に収まるよう、必要に応じて自動的に縮退レベルを切り替えます。
 */
export function generateHandoverPack(
  data: ProjectAnalysisData,
  options: HandoverPackOptions = {}
): { markdown: string; fallbackLevel: number; estimatedTokens: number } {
  const maxTokens = options.maxTokens || 4000;

  // 縮退レベル 0 から 5 まで順にシミュレーション
  for (let level = 0; level <= 5; level++) {
    const markdown = buildMarkdownForLevel(data, level);
    const tokens = estimateTokens(markdown);

    // 目標トークン数以下に収まった場合、または最終レベルに達した場合はそれを返す
    if (tokens <= maxTokens || level === 5) {
      return {
        markdown,
        fallbackLevel: level,
        estimatedTokens: tokens
      };
    }
  }

  // フォールバック
  const fallbackMarkdown = buildMarkdownForLevel(data, 5);
  return {
    markdown: fallbackMarkdown,
    fallbackLevel: 5,
    estimatedTokens: estimateTokens(fallbackMarkdown)
  };
}

/**
 * 指定された縮退レベルで Markdown をビルドします。
 * 
 * レベル定義:
 * 0: フル出力 (自動抽出された情報を余すことなく詳細に出力)
 * 1: Completed Tasks の出力を直近の最大10件のみに制限
 * 2: Completed Tasks の箇条書きを完全省略し、要約件数のみにする
 * 3: Next Task のリストを最大3件、Constraints のリストを最大3件に制限
 * 4: Known Issues セクションを完全省略
 * 5: Projectセクションの説明文を省略し、最小限のステータス情報と現在/次のタスクのみにする
 */
function buildMarkdownForLevel(data: ProjectAnalysisData, level: number): string {
  const sections: string[] = [];

  // 1. Title
  sections.push('# Chat Continuation Summary');

  // 2. Project Section
  sections.push('## Project');
  const projectDesc = extractProjectDescription(data, level);
  sections.push(projectDesc);

  // 3. Current Status
  sections.push('## Current Status');
  const currentStatus = extractCurrentStatus(data);
  sections.push(currentStatus);

  // 4. Completed Tasks
  sections.push('## Completed Tasks');
  const completedTasks = extractCompletedTasks(data);
  if (level >= 2) {
    sections.push(`- ${completedTasks.length} task(s) completed successfully. (Details omitted due to optimization level)`);
  } else if (level === 1 && completedTasks.length > 10) {
    const subset = completedTasks.slice(0, 10);
    sections.push(subset.map(t => `- [x] ${t}`).join('\n') + `\n- ...and ${completedTasks.length - 10} more completed task(s) omitted.`);
  } else {
    sections.push(completedTasks.map(t => `- [x] ${t}`).join('\n'));
  }

  // 5. Current Task
  sections.push('## Current Task');
  const currentTasks = extractCurrentTasks(data);
  sections.push(currentTasks.map(t => `- [/] ${t}`).join('\n'));

  // 6. Next Task
  sections.push('## Next Task');
  const nextTasks = extractNextTasks(data);
  if (level >= 3 && nextTasks.length > 3) {
    const subset = nextTasks.slice(0, 3);
    sections.push(subset.map(t => `- [ ] ${t}`).join('\n') + `\n- ...and ${nextTasks.length - 3} more task(s) planned.`);
  } else {
    sections.push(nextTasks.map(t => `- [ ] ${t}`).join('\n'));
  }

  // 7. Constraints (レベル5では簡略化)
  if (level < 5) {
    sections.push('## Constraints');
    const constraints = extractConstraints(data);
    if (level >= 3 && constraints.length > 3) {
      const subset = constraints.slice(0, 3);
      sections.push(subset.map(c => `- ${c}`).join('\n') + `\n- (Additional rules/constraints omitted)`);
    } else {
      sections.push(constraints.map(c => `- ${c}`).join('\n'));
    }
  }

  // 8. Known Issues (レベル4以上は省略)
  if (level < 4) {
    sections.push('## Known Issues');
    const issues = extractKnownIssues(data);
    sections.push(issues.map(i => `- ${i}`).join('\n'));
  }

  return sections.join('\n\n');
}

/**
 * プロジェクト概要の抽出
 */
function extractProjectDescription(data: ProjectAnalysisData, level: number): string {
  const baseMeta = `- **Name**: ${data.projectName}
- **Scale**: ${data.files.length} files (${(data.totalBytes / 1024).toFixed(1)} KB)`;

  if (level >= 5) {
    return baseMeta;
  }

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  const readmeFile = data.files.find(f => f.name.toLowerCase() === 'readme.md');
  const sourceFile = planFile || readmeFile;

  if (sourceFile && sourceFile.content) {
    const lines = sourceFile.content.split('\n');
    let foundHeader = false;
    const descLines: string[] = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('#') && !trimmed.startsWith('##')) {
        foundHeader = true;
        continue;
      }
      if (foundHeader) {
        if (trimmed.startsWith('##')) {
          break; // 次の見出しで打切り
        }
        if (trimmed !== '') {
          descLines.push(trimmed);
        }
      }
    }
    if (descLines.length > 0) {
      // 最初の1段落もしくは200文字程度を出力
      const desc = descLines.join(' ');
      const truncatedDesc = desc.length > 250 ? desc.substring(0, 247) + '...' : desc;
      return `${baseMeta}\n- **Summary**: ${truncatedDesc}`;
    }
  }

  return `${baseMeta}\n- **Summary**: Standard Vite/React/TypeScript or Python workspace.`;
}

/**
 * 現在の進捗状況を PROJECT_PLAN.md 等から抽出
 */
function extractCurrentStatus(data: ProjectAnalysisData): string {
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    // 全体進捗率を探す
    const progressMatch = planFile.content.match(/(?:全体進捗率|Progress)\s*[:：]\s*(.+)/);
    if (progressMatch) {
      return `Progress: ${progressMatch[1].trim()}`;
    }

    // 現在地を探す
    const currentLocMatch = planFile.content.match(/(?:現在地|【現在地】|Current Location)\s*[:：]\s*(.+)/);
    if (currentLocMatch) {
      return `Current Phase: ${currentLocMatch[1].trim()}`;
    }
  }
  return `Analyzing development state. Total estimated tokens: ${data.totalTokens.toLocaleString()}.`;
}

/**
 * 完了済みタスクの抽出
 */
function extractCompletedTasks(data: ProjectAnalysisData): string[] {
  const tasks: string[] = [];
  const taskFile = data.files.find(f => f.name.toLowerCase() === 'task.md');

  if (taskFile && taskFile.content) {
    const lines = taskFile.content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('-') && (trimmed.includes('[x]') || trimmed.includes('[X]'))) {
        const text = trimmed.replace(/^-\s*\[[xX]\]\s*/, '').trim();
        if (text) tasks.push(text);
      }
    }
  }

  // PROJECT_PLAN.md からも補完
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      const tableMatch = line.match(/\|\s*\*\*Phase\s*(\d+)\*\*\s*\|\s*`\[x\]`\s*完了\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        tasks.push(`Phase ${tableMatch[1]} Completed: ${tableMatch[2].trim()}`);
      }
    }
  }

  // 重複排除とフォールバック
  const uniqueTasks = Array.from(new Set(tasks));
  return uniqueTasks.length > 0 ? uniqueTasks : ['Setup initial project workspace structure.'];
}

/**
 * 進行中タスクの抽出
 */
function extractCurrentTasks(data: ProjectAnalysisData): string[] {
  const tasks: string[] = [];
  const taskFile = data.files.find(f => f.name.toLowerCase() === 'task.md');

  if (taskFile && taskFile.content) {
    const lines = taskFile.content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('-') && trimmed.includes('[/]')) {
        const text = trimmed.replace(/^-\s*\[\/\]\s*/, '').trim();
        if (text) tasks.push(text);
      }
    }
  }

  // PROJECT_PLAN.md から次回予定や現在地を補完
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const nextTaskMatch = planFile.content.match(/(?:次回タスク|【次回タスク】|Next Task)\s*[:：]\s*\n*\s*-\s*(.+)/);
    if (nextTaskMatch) {
      tasks.push(nextTaskMatch[1].trim());
    }
  }

  const uniqueTasks = Array.from(new Set(tasks));
  return uniqueTasks.length > 0 ? uniqueTasks : ['Implementing scheduled features.'];
}

/**
 * 未着手タスクの抽出
 */
function extractNextTasks(data: ProjectAnalysisData): string[] {
  const tasks: string[] = [];
  const taskFile = data.files.find(f => f.name.toLowerCase() === 'task.md');

  if (taskFile && taskFile.content) {
    const lines = taskFile.content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('-') && trimmed.includes('[ ]')) {
        const text = trimmed.replace(/^-\s*\[\s*\]\s*/, '').trim();
        if (text) tasks.push(text);
      }
    }
  }

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      const tableMatch = line.match(/\|\s*\*\*Phase\s*(\d+)\*\*\s*\|\s*`\[\s*\]`\s*未着手\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        tasks.push(`Phase ${tableMatch[1]} Pending: ${tableMatch[2].trim()}`);
      }
    }
  }

  const uniqueTasks = Array.from(new Set(tasks));
  return uniqueTasks.length > 0 ? uniqueTasks : ['Further feature expansion and optimizations.'];
}

/**
 * 制約条件の抽出
 */
function extractConstraints(data: ProjectAnalysisData): string[] {
  const constraints: string[] = [];
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');

  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    let inSection = false;
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('##') && (trimmed.includes('成功条件') || trimmed.includes('防衛方針') || trimmed.includes('Constraints') || trimmed.includes('DoD'))) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break; // 次のセクションへ移ったら終了
        }
        if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          const text = trimmed.replace(/^[-*]\s*(\[[ xX/]+\])?\s*/, '').trim();
          if (text) constraints.push(text);
        }
      }
    }
  }

  const uniqueConstraints = Array.from(new Set(constraints));
  if (uniqueConstraints.length > 0) {
    return uniqueConstraints;
  }

  // デフォルトフォールバック
  return [
    'Secure offline client-side only processing (no network transmission).',
    'Follow single responsibility principle (1 file 1 component/logic).',
    'Strictly avoid full-file rewrites during refactoring.'
  ];
}

/**
 * 既知の課題の抽出
 */
function extractKnownIssues(data: ProjectAnalysisData): string[] {
  const issues: string[] = [];
  const recordFile = data.files.find(f => f.name.toLowerCase() === 'record.md');
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  const targetFile = recordFile || planFile;

  if (targetFile && targetFile.content) {
    const lines = targetFile.content.split('\n');
    let inSection = false;
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('##') && (trimmed.includes('課題') || trimmed.includes('懸念') || trimmed.includes('Known Issues') || trimmed.includes('Issues'))) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          const text = trimmed.replace(/^[-*]\s*/, '').trim();
          if (text) issues.push(text);
        }
      }
    }
  }

  const uniqueIssues = Array.from(new Set(issues));
  return uniqueIssues.length > 0 ? uniqueIssues : ['None reported. Code runs cleanly and passes scans.'];
}

import { ProjectAnalysisData } from '../parser/types';
import { estimateTokens } from '../parser/token-estimator';

export interface PhaseSummaryPackOptions {
  maxTokens?: number; // 目標最大トークン数（デフォルト 4000）
}

interface ParsedPhase {
  number: number;
  status: string;
  isCompleted: boolean;
  content: string;
}

/**
 * プロジェクト解析データから、フェーズ完了時の引き継ぎ用まとめ（Phase Summary Pack）を自動生成します。
 * 目標トークン数に収まるよう、必要に応じて自動的に縮退レベルを切り替えます。
 */
export function generatePhaseSummaryPack(
  data: ProjectAnalysisData,
  options: PhaseSummaryPackOptions = {}
): { markdown: string; fallbackLevel: number; estimatedTokens: number } {
  const maxTokens = options.maxTokens || 4000;

  // 縮退レベル 0 から 5 まで順にシミュレーション
  for (let level = 0; level <= 5; level++) {
    const markdown = buildMarkdownForLevel(data, level);
    const tokens = estimateTokens(markdown);

    // 目標トークン数以下に収まった場合、または最終レベルに達した場合はそれを返す
    if (tokens <= maxTokens || level === 5) {
      return {
        markdown,
        fallbackLevel: level,
        estimatedTokens: tokens
      };
    }
  }

  // フォールバック
  const fallbackMarkdown = buildMarkdownForLevel(data, 5);
  return {
    markdown: fallbackMarkdown,
    fallbackLevel: 5,
    estimatedTokens: estimateTokens(fallbackMarkdown)
  };
}

/**
 * 指定された縮退レベルで Markdown をビルドします。
 * 
 * レベル定義:
 * 0: フル出力 (完了/未完了タスクの詳細、全ファイルのモジュール解析情報を含む)
 * 1: Completed Tasks (完了事項) のうち、直近の完了フェーズのみ詳細表示し、古いフェーズは省略
 * 2: Current Status (コード状態) における各ファイルのモジュール詳細（クラス/関数）を省略
 * 3: Next Actions (次タスク) のうち、直近の未完了フェーズのみ詳細表示し、それ以降は省略
 * 4: Current Status (コード状態) のファイル一覧を省略し、主要な変更のあった主要ファイルリスト（最大5件）のみ表示
 * 5: 完了事項・次のタスクを要約し、コード状態はファイル総数と総サイズのみの最小構成
 */
function buildMarkdownForLevel(data: ProjectAnalysisData, level: number): string {
  const sections: string[] = [];
  const { phases, progressText } = parseProjectPlan(data);

  // 完了した最新フェーズを特定
  const completedPhases = phases.filter(p => p.isCompleted);
  const pendingPhases = phases.filter(p => !p.isCompleted);
  const latestCompletedPhase = completedPhases.length > 0 ? completedPhases[completedPhases.length - 1] : null;

  // 1. Title
  const phaseTitle = latestCompletedPhase 
    ? `Phase ${latestCompletedPhase.number} 完了` 
    : '開発状況サマリー';
  sections.push(`# 【引継ぎ】${data.projectName} - ${phaseTitle}`);

  // 2. 完了事項 (Completed)
  sections.push('## 1. 完了事項 (Completed)');
  sections.push(buildCompletedSection(completedPhases, latestCompletedPhase, level));

  // 3. 現在のコード状態 (Current Status)
  sections.push('## 2. 現在のコード状態 (Current Status)');
  sections.push(buildCurrentStatusSection(data, progressText, level));

  // 4. 次フェーズのタスク (Next Actions)
  sections.push('## 3. 次フェーズのタスク (Next Actions)');
  sections.push(buildNextActionsSection(pendingPhases, level));

  return sections.join('\n\n');
}

/**
 * PROJECT_PLAN.md からフェーズ情報と進捗率を抽出する
 */
function parseProjectPlan(data: ProjectAnalysisData): { phases: ParsedPhase[]; progressText: string } {
  const phases: ParsedPhase[] = [];
  let progressText = '未定 (0/0 フェーズ完了)';

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      // 進捗率の抽出: 全体進捗率: ▓▓▓▓▓▓▓▓░░ 66% (8/12 フェーズ完了)
      if (line.includes('全体進捗率')) {
        const match = line.match(/全体進捗率\s*(?:\*\*)?\s*:\s*([^\n]+)/);
        if (match) {
          progressText = match[1].trim();
        }
      }

      // テーブル行の抽出: | **Phase 1** | `[x]` 完了 | 基盤構築... |
      // または | **Phase 1** | `[ ]` 未着手 | ... |
      const tableMatch = line.match(/\|\s*\*\*(Phase\s*(\d+))\*\*\s*\|\s*([^|]+)\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        const phaseNum = parseInt(tableMatch[2], 10);
        const statusText = tableMatch[3].trim();
        const contentText = tableMatch[4].trim();

        const isCompleted = statusText.includes('[x]') || statusText.includes('完了');
        phases.push({
          number: phaseNum,
          status: statusText,
          isCompleted,
          content: contentText
        });
      }
    }
  }

  // 重複を除去
  const uniquePhases: ParsedPhase[] = [];
  const phaseNumbers = new Set<number>();
  for (const p of phases) {
    if (!phaseNumbers.has(p.number)) {
      phaseNumbers.add(p.number);
      uniquePhases.push(p);
    }
  }

  // フェーズが取れなかった場合のデフォルト
  if (uniquePhases.length === 0) {
    // 仮の構成を設定
    uniquePhases.push({ number: 1, status: '`[x]` 完了', isCompleted: true, content: '基盤設計および環境構築' });
    uniquePhases.push({ number: 2, status: '`[x]` 完了', isCompleted: true, content: 'コアモジュールと静的解析エンジンの実装' });
    uniquePhases.push({ number: 3, status: '`[/]` 進行中', isCompleted: false, content: 'UIコンポーネントの構築と統合' });
  }

  return { phases: uniquePhases, progressText };
}

/**
 * 完了事項セクションの構築
 */
function buildCompletedSection(
  completedPhases: ParsedPhase[],
  latestCompleted: ParsedPhase | null,
  level: number
): string {
  if (completedPhases.length === 0) {
    return '- 特になし（開発開始前）';
  }

  if (level >= 5) {
    if (latestCompleted) {
      return `- Phase ${latestCompleted.number} までの開発（${latestCompleted.content.split('（')[0].split('(')[0]} 等）が完了。`;
    }
    return `- 初期フェーズの開発が完了。`;
  }

  if (level >= 1) {
    // 直近の完了フェーズのみ詳細を出し、それ以外は1行にまとめる
    const list: string[] = [];
    if (latestCompleted) {
      list.push(`- **Phase ${latestCompleted.number} [完了]**: ${latestCompleted.content}`);
    }
    const olderCount = completedPhases.length - (latestCompleted ? 1 : 0);
    if (olderCount > 0) {
      const olderPhasesText = completedPhases
        .filter(p => p.number !== latestCompleted?.number)
        .map(p => `Phase ${p.number}`)
        .join(', ');
      list.push(`- (過去完了分: ${olderPhasesText} は正常に完了済)`);
    }
    return list.join('\n');
  }

  // レベル 0: 全て詳細表示
  return completedPhases
    .map(p => `- **Phase ${p.number} [完了]**: ${p.content}`)
    .join('\n');
}

/**
 * 現在のコード状態セクションの構築
 */
function buildCurrentStatusSection(data: ProjectAnalysisData, progressText: string, level: number): string {
  const fileLines: string[] = [];

  fileLines.push(`- **進捗率**: ${progressText}`);

  if (level >= 5) {
    fileLines.push(`- **主要ファイル構成**: 全 ${data.files.length} ファイル (${(data.totalBytes / 1024).toFixed(1)} KB)`);
    return fileLines.join('\n');
  }

  // 変更のあった主要ファイルやソースコードファイルを取得する
  const sourceFiles = data.files.filter(f => {
    const ext = f.name.substring(f.name.lastIndexOf('.')).toLowerCase();
    return ['.ts', '.tsx', '.js', '.jsx', '.py', '.css'].includes(ext);
  });

  if (level >= 4) {
    fileLines.push(`- **主要ファイル構成** (上位5件を表示):`);
    const sorted = [...sourceFiles].sort((a, b) => b.size - a.size).slice(0, 5);
    for (const f of sorted) {
      fileLines.push(`  - [${f.name}](file:///${f.path.replace(/\\/g, '/')}) (${(f.size / 1024).toFixed(1)} KB)`);
    }
    if (sourceFiles.length > 5) {
      fileLines.push(`  - ...他 ${sourceFiles.length - 5} 個のソースファイル`);
    }
    return fileLines.join('\n');
  }

  fileLines.push(`- **主要ファイルの配置と動作状態**:`);
  for (const f of data.files) {
    // 無駄に大きいノード等はスキップしつつ表示
    const isSource = sourceFiles.some(sf => sf.path === f.path);
    if (!isSource && f.size > 20000) continue; // 大きい非ソースは省略

    let detail = `(${(f.size / 1024).toFixed(1)} KB)`;
    if (level < 2 && f.analysis) {
      const parts: string[] = [];
      if (f.analysis.classes.length > 0) {
        parts.push(`Classes: ${f.analysis.classes.map(c => c.name).join(', ')}`);
      }
      if (f.analysis.functions.length > 0) {
        // 先頭5つだけ
        const fns = f.analysis.functions.slice(0, 5).map(fn => fn.name).join(', ');
        parts.push(`Funcs: ${fns}${f.analysis.functions.length > 5 ? '...' : ''}`);
      }
      if (parts.length > 0) {
        detail += ` - ${parts.join(' | ')}`;
      }
    }
    fileLines.push(`  - [${f.name}](file:///${f.path.replace(/\\/g, '/')}) ${detail}`);
  }

  return fileLines.join('\n');
}

/**
 * 次フェーズのタスクセクションの構築
 */
function buildNextActionsSection(pendingPhases: ParsedPhase[], level: number): string {
  if (pendingPhases.length === 0) {
    return '- 特になし（すべてのフェーズが完了しています）';
  }

  if (level >= 5) {
    const next = pendingPhases[0];
    return `- 次回タスク: Phase ${next.number} (${next.content.split('（')[0].split('(')[0]}) に着手予定。`;
  }

  if (level >= 3) {
    const next = pendingPhases[0];
    const list: string[] = [];
    list.push(`- **Phase ${next.number} [未着手]**: ${next.content}`);
    if (pendingPhases.length > 1) {
      const remaining = pendingPhases.slice(1).map(p => `Phase ${p.number}`).join(', ');
      list.push(`- (以降の計画: ${remaining} は順次着手予定)`);
    }
    return list.join('\n');
  }

  // レベル 0, 1, 2: すべて表示
  return pendingPhases
    .map(p => `- **Phase ${p.number} [未着手]**: ${p.content}`)
    .join('\n');
}

import { ProjectAnalysisData } from '../parser/types';
import { estimateTokens } from '../parser/token-estimator';

export interface TransferPackOptions {
  maxTokens?: number; // 目標最大トークン数（デフォルト 4000）
}

/**
 * 異なるAIモデル間での移行を目的として、プロジェクト概要や機能一覧をまとめる
 * AI Transfer Pack (Markdown) を生成します。
 * 目標トークン数に収まるよう、必要に応じて自動的に縮退レベルを切り替えます。
 */
export function generateTransferPack(
  data: ProjectAnalysisData,
  options: TransferPackOptions = {}
): { markdown: string; fallbackLevel: number; estimatedTokens: number } {
  const maxTokens = options.maxTokens || 4000;

  // 縮退レベル 0 から 5 まで順にシミュレーション
  for (let level = 0; level <= 5; level++) {
    const markdown = buildMarkdownForLevel(data, level);
    const tokens = estimateTokens(markdown);

    // 目標トークン数以下に収まった場合、または最終レベルに達した場合はそれを返す
    if (tokens <= maxTokens || level === 5) {
      return {
        markdown,
        fallbackLevel: level,
        estimatedTokens: tokens
      };
    }
  }

  // フォールバック
  const fallbackMarkdown = buildMarkdownForLevel(data, 5);
  return {
    markdown: fallbackMarkdown,
    fallbackLevel: 5,
    estimatedTokens: estimateTokens(fallbackMarkdown)
  };
}

/**
 * 指定された縮退レベルで Markdown をビルドします。
 * 
 * レベル定義:
 * 0: フル出力 (各セクション詳細に出力、Design Decisions や Feature List を制限なしで表示)
 * 1: Completed Features の項目数を直近の最大10件のみに制限 (残りは件数のみ)
 * 2: Completed Features を完全省略 (要約件数のみ) し、Design Decisions を直近の 5 件に制限
 * 3: Feature List の詳細説明を省略し項目名のみ。Recommended Next Actions を最大3件、Constraints を最大3件に制限。
 * 4: Design Decisions セクションを完全省略
 * 5: Project Overview の説明文を最小限（メタ情報のみ）にし、Architecture セクションも極めてシンプルにする。
 */
function buildMarkdownForLevel(data: ProjectAnalysisData, level: number): string {
  const sections: string[] = [];

  // 1. Title
  sections.push('# AI Transfer Package');

  // 2. Project Overview
  sections.push('## Project Overview');
  const projectOverview = extractProjectOverview(data, level);
  sections.push(projectOverview);

  // 3. Architecture
  sections.push('## Architecture');
  const architecture = inferArchitecture(data, level);
  sections.push(architecture);

  // 4. Feature List
  sections.push('## Feature List');
  const features = extractFeatureList(data, level);
  sections.push(features.map(f => `- ${f}`).join('\n'));

  // 5. Completed Features
  sections.push('## Completed Features');
  const completed = extractCompletedFeatures(data);
  if (level >= 2) {
    sections.push(`- ${completed.length} feature(s)/task(s) completed. (Details omitted due to optimization level)`);
  } else if (level === 1 && completed.length > 10) {
    const subset = completed.slice(0, 10);
    sections.push(subset.map(c => `- [x] ${c}`).join('\n') + `\n- ...and ${completed.length - 10} more completed feature(s) omitted.`);
  } else {
    sections.push(completed.map(c => `- [x] ${c}`).join('\n'));
  }

  // 6. Current Status
  sections.push('## Current Status');
  const currentStatus = extractCurrentStatus(data);
  sections.push(currentStatus);

  // 7. Constraints (レベル5では簡略表示、レベル3以上では件数制限)
  sections.push('## Constraints');
  const constraints = extractConstraints(data);
  if (level >= 3 && constraints.length > 3) {
    const subset = constraints.slice(0, 3);
    sections.push(subset.map(c => `- ${c}`).join('\n') + `\n- (Additional constraints omitted)`);
  } else {
    sections.push(constraints.map(c => `- ${c}`).join('\n'));
  }

  // 8. Design Decisions (レベル4以上は省略、レベル2では最大5件)
  if (level < 4) {
    sections.push('## Design Decisions');
    const decisions = extractDesignDecisions(data);
    if (level >= 2 && decisions.length > 5) {
      const subset = decisions.slice(0, 5);
      sections.push(subset.map(d => `- ${d}`).join('\n') + `\n- (Additional decisions omitted)`);
    } else {
      sections.push(decisions.map(d => `- ${d}`).join('\n'));
    }
  }

  // 9. Recommended Next Actions (レベル3以上では最大3件)
  sections.push('## Recommended Next Actions');
  const nextActions = extractRecommendedNextActions(data);
  if (level >= 3 && nextActions.length > 3) {
    const subset = nextActions.slice(0, 3);
    sections.push(subset.map(a => `- [ ] ${a}`).join('\n') + `\n- ...and ${nextActions.length - 3} more recommended action(s) planned.`);
  } else {
    sections.push(nextActions.map(a => `- [ ] ${a}`).join('\n'));
  }

  return sections.join('\n\n');
}

/**
 * プロジェクト概要の抽出
 */
function extractProjectOverview(data: ProjectAnalysisData, level: number): string {
  const baseMeta = `- **Name**: ${data.projectName}
- **Scale**: ${data.files.length} files (${(data.totalBytes / 1024).toFixed(1)} KB)`;

  if (level >= 5) {
    return baseMeta;
  }

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  const readmeFile = data.files.find(f => f.name.toLowerCase() === 'readme.md');
  const sourceFile = planFile || readmeFile;

  if (sourceFile && sourceFile.content) {
    const lines = sourceFile.content.split('\n');
    let foundHeader = false;
    const descLines: string[] = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('#') && !trimmed.startsWith('##')) {
        foundHeader = true;
        continue;
      }
      if (foundHeader) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed !== '') {
          descLines.push(trimmed);
        }
      }
    }
    if (descLines.length > 0) {
      const desc = descLines.join(' ');
      const truncatedDesc = desc.length > 300 ? desc.substring(0, 297) + '...' : desc;
      return `${baseMeta}\n- **Summary**: ${truncatedDesc}`;
    }
  }

  return `${baseMeta}\n- **Summary**: Standard Vite/React/TypeScript or Python workspace.`;
}

/**
 * アーキテクチャ構成を推測
 */
function inferArchitecture(data: ProjectAnalysisData, level: number): string {
  if (level >= 5) {
    return 'Client-side local execution workspace (React/Vite/TypeScript architecture).';
  }

  const paths = data.files.map(f => f.path);
  const notes: string[] = [];

  const hasComponents = paths.some(p => p.includes('src/components'));
  const hasApp = paths.some(p => p.includes('src/app'));
  const hasLib = paths.some(p => p.includes('src/lib'));
  const hasParser = paths.some(p => p.includes('src/lib/parser'));
  const hasFormatters = paths.some(p => p.includes('src/lib/formatters'));

  if (hasApp) {
    notes.push('- **Application Entry**: UI components and entry routes are located under `src/app/`.');
  }
  if (hasComponents) {
    notes.push('- **UI Components**: UI presentation components are structured in `src/components/`.');
  }
  if (hasLib) {
    notes.push('- **Core Library**: Core logics and formatters are placed under `src/lib/`.');
  }
  if (hasParser) {
    notes.push('- **Analysis Engines**: Abstract AST/file tree parsers are encapsulated in `src/lib/parser/`.');
  }
  if (hasFormatters) {
    notes.push('- **Output Formatters**: Format-specific layout modules are located in `src/lib/formatters/`.');
  }

  if (notes.length === 0) {
    notes.push('- Standard codebase layout configuration.');
  }

  return 'Codebase layout configuration:\n' + notes.join('\n');
}

/**
 * 機能一覧の抽出
 */
function extractFeatureList(data: ProjectAnalysisData, level: number): string[] {
  const features: string[] = [];
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');

  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      // 工程管理表のテーブル行からフェーズ名とタスク内容を抽出
      const tableMatch = line.match(/\|\s*\*\*(Phase\s*\d+)\*\*\s*\|\s*([^|]+)\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        const phaseName = tableMatch[1].trim();
        const statusText = tableMatch[2].trim();
        const taskContent = tableMatch[3].trim();

        if (level >= 3) {
          // 詳細説明を省略、タイトルのみ
          features.push(`${phaseName}: ${taskContent.split('（')[0].split('(')[0].trim()}`);
        } else {
          features.push(`${phaseName} (${statusText}): ${taskContent}`);
        }
      }
    }
  }

  if (features.length > 0) {
    return features;
  }

  return [
    'Project Structure Scanning (File tree parsing)',
    'Module Definition Analysis (API, Classes, Functions extractor)',
    'Dependency Mapping (File imports parser)',
    'Token Estimation & Read Time calculator',
    'Audit Pack & Handover Pack Generation UI'
  ];
}

/**
 * 実装済み機能の抽出
 */
function extractCompletedFeatures(data: ProjectAnalysisData): string[] {
  const completed: string[] = [];
  const taskFile = data.files.find(f => f.name.toLowerCase() === 'task.md');

  if (taskFile && taskFile.content) {
    const lines = taskFile.content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('-') && (trimmed.includes('[x]') || trimmed.includes('[X]'))) {
        const text = trimmed.replace(/^-\s*\[[xX]\]\s*/, '').trim();
        if (text) completed.push(text);
      }
    }
  }

  // PROJECT_PLAN.md からも補完
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      const tableMatch = line.match(/\|\s*\*\*(Phase\s*\d+)\*\*\s*\|\s*`\[x\]`\s*完了\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        completed.push(`Phase Completed: ${tableMatch[2].trim()}`);
      }
    }
  }

  const uniqueCompleted = Array.from(new Set(completed));
  return uniqueCompleted.length > 0 ? uniqueCompleted : ['Repository initialization and foundation layout setup.'];
}

/**
 * 現在の進捗状況を抽出
 */
function extractCurrentStatus(data: ProjectAnalysisData): string {
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const progressMatch = planFile.content.match(/(?:全体進捗率|Progress)\s*[:：]\s*(.+)/);
    if (progressMatch) {
      return `Progress: ${progressMatch[1].trim()}`;
    }
    const currentLocMatch = planFile.content.match(/(?:現在地|【現在地】|Current Location)\s*[:：]\s*(.+)/);
    if (currentLocMatch) {
      return `Current Phase: ${currentLocMatch[1].trim()}`;
    }
  }
  return `Analyzing development state. Total files analyzed: ${data.files.length}.`;
}

/**
 * 制約条件の抽出
 */
function extractConstraints(data: ProjectAnalysisData): string[] {
  const constraints: string[] = [];
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');

  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    let inSection = false;
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('##') && (trimmed.includes('成功条件') || trimmed.includes('防衛方針') || trimmed.includes('Constraints') || trimmed.includes('DoD'))) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          const text = trimmed.replace(/^[-*]\s*(\[[ xX/]+\])?\s*/, '').trim();
          if (text) constraints.push(text);
        }
      }
    }
  }

  const uniqueConstraints = Array.from(new Set(constraints));
  if (uniqueConstraints.length > 0) {
    return uniqueConstraints;
  }

  return [
    'Secure offline client-side only processing (no network transmission).',
    'Follow single responsibility principle (1 file 1 component/logic).',
    'Strictly avoid full-file rewrites during refactoring.'
  ];
}

/**
 * 技術選定・設計判断の抽出
 */
function extractDesignDecisions(data: ProjectAnalysisData): string[] {
  const decisions: string[] = [];
  const recordFile = data.files.find(f => f.name.toLowerCase() === 'record.md');
  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  const targetFile = recordFile || planFile;

  if (targetFile && targetFile.content) {
    const lines = targetFile.content.split('\n');
    let inSection = false;
    for (const line of lines) {
      const trimmed = line.trim();
      // 設計判断に関連する見出しを探す
      if (trimmed.startsWith('##') && (
        trimmed.includes('技術決定') || 
        trimmed.includes('設計判断') || 
        trimmed.includes('意思決定') || 
        trimmed.includes('技術選定') || 
        trimmed.includes('Decision') || 
        trimmed.includes('設計上の決定')
      )) {
        inSection = true;
        continue;
      }
      if (inSection) {
        if (trimmed.startsWith('##')) {
          break;
        }
        if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          const text = trimmed.replace(/^[-*]\s*/, '').trim();
          if (text) decisions.push(text);
        }
      }
    }
  }

  const uniqueDecisions = Array.from(new Set(decisions));
  if (uniqueDecisions.length > 0) {
    return uniqueDecisions;
  }

  return [
    'Strict offline-first architecture using showDirectoryPicker for safety.',
    'Separation of concerns: AST parsing (parser/) and Markdown presentation (formatters/).',
    'Token estimator with weight logic to simulate LLM contexts locally.',
    'Responsive dark-theme UI implemented with tailwindcss.'
  ];
}

/**
 * 推奨される次のアクション
 */
function extractRecommendedNextActions(data: ProjectAnalysisData): string[] {
  const actions: string[] = [];
  const taskFile = data.files.find(f => f.name.toLowerCase() === 'task.md');

  if (taskFile && taskFile.content) {
    const lines = taskFile.content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('-') && trimmed.includes('[ ]')) {
        const text = trimmed.replace(/^-\s*\[\s*\]\s*/, '').trim();
        if (text) actions.push(text);
      }
    }
  }

  const planFile = data.files.find(f => f.name.toLowerCase() === 'project_plan.md');
  if (planFile && planFile.content) {
    const lines = planFile.content.split('\n');
    for (const line of lines) {
      const tableMatch = line.match(/\|\s*\*\*(Phase\s*\d+)\*\*\s*\|\s*`\[\s*\]`\s*未着手\s*\|\s*([^|]+)/i);
      if (tableMatch) {
        actions.push(`Phase Pending: ${tableMatch[2].trim()}`);
      }
    }
  }

  const uniqueActions = Array.from(new Set(actions));
  return uniqueActions.length > 0 ? uniqueActions : ['Further UI polish and performance verification.'];
}

import { generateAuditPack } from '../audit';
import { ProjectAnalysisData } from '../../parser/types';

// --- アサーションヘルパー ---
function assert(condition: boolean, message: string) {
  if (!condition) {
    throw new Error(`Assertion Failed: ${message}`);
  }
}

// --- 検証用モックデータの構築 ---
function buildMockProjectData(fileCount: number): ProjectAnalysisData {
  const files: any[] = [];

  // 大量のモックファイルを作成して情報量を増やす
  for (let i = 1; i <= fileCount; i++) {
    const isTest = i % 3 === 0;
    const isConfig = i % 5 === 0;
    const fileName = isTest ? `helper_${i}.test.ts` : isConfig ? `config_${i}.ts` : `service_${i}.ts`;
    const filePath = isTest 
      ? `src/services/__tests__/${fileName}` 
      : isConfig 
        ? `src/config/${fileName}` 
        : `src/services/${fileName}`;

    files.push({
      path: filePath,
      name: fileName,
      size: 5000,
      content: `// Source code for ${fileName}`,
      tokens: 1500,
      dependencies: [
        { importPath: 'fs', isExternal: true },
        { importPath: '../config/config_5', resolvedPath: 'src/config/config_5.ts', isExternal: false }
      ],
      analysis: {
        classes: [
          {
            name: `ServiceClass${i}`,
            extends: 'BaseService',
            description: `This is class ${i} used for system operation simulation.`,
            methods: [
              { name: 'initialize', arguments: ['config', 'options'], returnType: 'void', description: 'Initialize service instance' },
              { name: 'execute', arguments: ['param1'], returnType: 'Promise<boolean>', description: 'Execute service core logic' },
              { name: 'cleanup', arguments: [], returnType: 'void', description: 'Cleanup resources' }
            ]
          }
        ],
        functions: [
          {
            name: `globalUtility${i}`,
            arguments: ['input'],
            returnType: 'string',
            description: 'Convert input to uppercase string'
          }
        ],
        exports: [`ServiceClass${i}`, `globalUtility${i}`]
      }
    });
  }

  // 木構造アスキーアート
  let folderStructureText = 'project-root/\n';
  folderStructureText += '├── package.json\n';
  folderStructureText += '└── src/\n';
  folderStructureText += '    ├── config/\n';
  folderStructureText += '    │   ├── config_5.ts\n';
  folderStructureText += '    │   └── config_10.ts\n';
  folderStructureText += '    └── services/\n';
  folderStructureText += '        ├── service_1.ts\n';
  folderStructureText += '        ├── service_2.ts\n';
  folderStructureText += '        └── __tests__/\n';
  folderStructureText += '            ├── helper_3.test.ts\n';
  folderStructureText += '            └── helper_6.test.ts\n';

  return {
    projectName: 'Verification Project',
    files,
    folderStructureText,
    totalBytes: fileCount * 5000,
    totalTokens: fileCount * 1500
  };
}

function runTests() {
  console.log('=== START AUDIT PACK GENERATION TESTING ===\n');

  const data = buildMockProjectData(15);
  console.log(`Mock Project Stats: Files=${data.files.length}, Bytes=${data.totalBytes}`);

  // Test 1: 十分に大きいトークン制限（縮退レベル0: フル）
  console.log('Test 1: Generates full pack (Level 0)');
  const res0 = generateAuditPack(data, { maxTokens: 10000 });
  console.log(`Estimated Tokens: ${res0.estimatedTokens}, Fallback Level: ${res0.fallbackLevel}`);
  assert(res0.fallbackLevel === 0, 'Should use level 0 when token limit is very high');
  assert(res0.markdown.includes('initialize(config, options)'), 'Level 0 should contain full signature');
  assert(res0.markdown.includes('Initialize service instance'), 'Level 0 should contain JSDoc');
  assert(res0.markdown.includes('helper_3.test.ts'), 'Level 0 should contain test files');

  // Test 2: 中程度のトークン制限（縮退レベル1〜2）
  console.log('Test 2: Generates optimized pack (JSDoc omitted - Level 1/2)');
  // レベル1ではJSDocが除外される
  const res1 = generateAuditPack(data, { maxTokens: 2000 });
  console.log(`Estimated Tokens: ${res1.estimatedTokens}, Fallback Level: ${res1.fallbackLevel}`);
  assert(res1.fallbackLevel >= 1, 'Should fall back to level 1 or higher');
  assert(res1.estimatedTokens <= 2000, 'Should respect token limit');

  if (res1.fallbackLevel === 1) {
    assert(!res1.markdown.includes('Initialize service instance'), 'Level 1 should omit description');
    assert(res1.markdown.includes('initialize(config, options)'), 'Level 1 should keep method signature');
  }

  // Test 3: 厳しいトークン制限（縮退レベル3: テストファイル等除外）
  console.log('Test 3: Generates compact pack (Tests/configs omitted - Level 3)');
  const res3 = generateAuditPack(data, { maxTokens: 1500 });
  console.log(`Estimated Tokens: ${res3.estimatedTokens}, Fallback Level: ${res3.fallbackLevel}`);
  assert(res3.fallbackLevel >= 3, 'Should fall back to level 3 or higher');
  assert(res3.estimatedTokens <= 1500, 'Should respect token limit');

  const moduleMapSection = res3.markdown.substring(res3.markdown.indexOf('## Module Map'));
  assert(!moduleMapSection.includes('helper_3.test.ts'), 'Level 3 should omit test files from module map');

  // Test 4: 極めて厳しい制限（縮退レベル4: Module Map完全省略）
  console.log('Test 4: Generates minimal pack (Module map completely omitted - Level 4)');
  const res4 = generateAuditPack(data, { maxTokens: 800 });
  console.log(`Estimated Tokens: ${res4.estimatedTokens}, Fallback Level: ${res4.fallbackLevel}`);
  assert(res4.fallbackLevel >= 4, 'Should fall back to level 4 or higher');
  assert(res4.estimatedTokens <= 800, 'Should respect token limit');
  assert(!res4.markdown.includes('## Module Map'), 'Level 4 should completely omit module map section');

  // Test 5: 限界値テスト
  console.log('Test 5: Check boundary handling (Level 5)');
  const res5 = generateAuditPack(data, { maxTokens: 200 });
  console.log(`Estimated Tokens: ${res5.estimatedTokens}, Fallback Level: ${res5.fallbackLevel}`);
  assert(res5.fallbackLevel === 5, 'Should fall back to maximum level 5');

  console.log('\n================================================');
  console.log('🎉 AUDIT PACK TESTS PASSED SUCCESSFULLY! 🎉');
  console.log('================================================');
}

// 実行
try {
  runTests();
  process.exit(0);
} catch (e: any) {
  console.error('\n❌ AUDIT PACK TEST FAILED ❌');
  console.error(e.message || e);
  process.exit(1);
}

