): boolean {
  // サイズ制限の検証
  if (size > maxBytes) {
    return false;
  }

  // 拡張子の検証
  const dotIndex = fileName.lastIndexOf('.');
  const ext = dotIndex !== -1 ? fileName.substring(dotIndex).toLowerCase() : '';
  if (excludedExts.has(ext) || excludedExts.has(fileName)) {
    return false;
  }

  return true;
}

/**
 * FileSystemFileHandle から安全にテキストコンテンツをデコードして読み込みます。
 * 
 * @param handle ファイルのハンドル
 */
export async function readFileContent(handle: FileSystemFileHandle): Promise<string> {
  try {
    const file = await handle.getFile();
    return await file.text();
  } catch (error) {
    console.error(`Failed to read file: ${handle.name}`, error);
    throw new Error(`ファイル「${handle.name}」の読み込みに失敗しました。: ${error instanceof Error ? error.message : String(error)}`);
  }
}

import { DEFAULT_EXCLUDED_DIRS, DEFAULT_EXCLUDED_EXTS } from '../config/constants';

export interface FileNode {
  name: string;
  path: string; // Relative path from the root
  kind: 'file' | 'directory';
  handle: FileSystemFileHandle | FileSystemDirectoryHandle;
  children?: FileNode[];
  size?: number;
}

export interface TraverseOptions {
  excludedDirs?: string[];
  excludedExts?: Set<string>;
}

/**
 * File System Access API を用いてディレクトリを再帰的に走査します。
 * 
 * @param dirHandle ルートまたはサブディレクトリのハンドル
 * @param currentPath ルートからの相対パス
 * @param options 除外設定などのオプション
 */
export async function traverseDirectory(
  dirHandle: FileSystemDirectoryHandle,
  currentPath = '',
  options: TraverseOptions = {}
): Promise<FileNode[]> {
  const excludedDirs = options.excludedDirs || DEFAULT_EXCLUDED_DIRS;
  const excludedExts = options.excludedExts || DEFAULT_EXCLUDED_EXTS;

  const nodes: FileNode[] = [];

  for await (const entry of (dirHandle as any).values()) {
    const relativePath = currentPath ? `${currentPath}/${entry.name}` : entry.name;

    if (entry.kind === 'directory') {
      if (excludedDirs.includes(entry.name)) {
        continue;
      }
      const children = await traverseDirectory(entry, relativePath, options);
      nodes.push({
        name: entry.name,
        path: relativePath,
        kind: 'directory',
        handle: entry,
        children
      });
    } else if (entry.kind === 'file') {
      const dotIndex = entry.name.lastIndexOf('.');
      const ext = dotIndex !== -1 ? entry.name.substring(dotIndex).toLowerCase() : '';

      // 拡張子またはファイル名自体が除外リストにあればスキップ
      if (excludedExts.has(ext) || excludedExts.has(entry.name)) {
        continue;
      }

      let size = 0;
      try {
        const file = await entry.getFile();
        size = file.size;
      } catch (e) {
        console.warn(`Failed to get file details for ${entry.name}:`, e);
      }

      nodes.push({
        name: entry.name,
        path: relativePath,
        kind: 'file',
        handle: entry,
        size
      });
    }
  }

  // ディレクトリが先、ファイルが後になるよう名前順でソート
  return nodes.sort((a, b) => {
    if (a.kind !== b.kind) {
      return a.kind === 'directory' ? -1 : 1;
    }
    return a.name.localeCompare(b.name);
  });
}

/**
 * バイト数を読みやすい形式（KB, MB 等）にフォーマットします。
 */
export function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  const val = parseFloat((bytes / Math.pow(k, i)).toFixed(1));
  return `${val} ${sizes[i]}`;
}

/**
 * 走査されたファイルノード配列から、視覚的なフォルダツリーテキストを生成します。
 */
export function generateTreeText(nodes: FileNode[], prefix = ''): string {
  let text = '';
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    const isLast = i === nodes.length - 1;
    const connector = isLast ? '└── ' : '├── ';

    if (node.kind === 'directory') {
      text += `${prefix}${connector}${node.name}/\n`;
      const nextPrefix = prefix + (isLast ? '    ' : '│   ');
      if (node.children && node.children.length > 0) {
        text += generateTreeText(node.children, nextPrefix);
      }
    } else {
      const sizeStr = node.size !== undefined ? ` (${formatBytes(node.size)})` : '';
      text += `${prefix}${connector}${node.name}${sizeStr}\n`;
    }
  }
  return text;
}

export interface FunctionInfo {
  name: string;
  arguments: string[];
  returnType?: string;
  description?: string;
  isExported?: boolean;
}

export interface ClassInfo {
  name: string;
  extends?: string;
  description?: string;
  methods: FunctionInfo[];
  isExported?: boolean;
}

export interface ModuleAnalysisResult {
  classes: ClassInfo[];
  functions: FunctionInfo[];
  exports: string[];
}

function getJsDocDescription(content: string, index: number): string | undefined {
  const beforeText = content.substring(0, index);
  const trimmed = beforeText.trimEnd();

  if (!trimmed.endsWith('*/')) {
    return undefined;
  }

  const lastDocStart = trimmed.lastIndexOf('/**');
  if (lastDocStart === -1) {
    return undefined;
  }

  const docComment = trimmed.substring(lastDocStart);
  if (docComment.includes('}') || docComment.includes(';')) {
    const lines = docComment.split('\n');
    const isClean = lines.every((line, idx) => {
      const l = line.trim();
      return idx === 0 ? l.startsWith('/**') : (l.startsWith('*') || l.startsWith('*/'));
    });
    if (!isClean) return undefined;
  }

  return docComment
    .replace(/^\/\*\*|\*\/$/g, '')
    .split('\n')
    .map(line => line.trim().replace(/^\*\s*/, ''))
    .filter(line => line.length > 0 && !line.startsWith('@'))
    .join('\n')
    .trim();
}

function getPythonDocstring(lines: string[], startLineIndex: number): string | undefined {
  let currentIdx = startLineIndex + 1;
  while (currentIdx < lines.length && lines[currentIdx].trim() === '') {
    currentIdx++;
  }

  if (currentIdx >= lines.length) return undefined;

  const line = lines[currentIdx].trim();
  let quoteChar = '';
  if (line.startsWith('"""')) quoteChar = '"""';
  else if (line.startsWith("'''")) quoteChar = "'''";

  if (!quoteChar) return undefined;

  if (line.endsWith(quoteChar) && line.length > quoteChar.length * 2) {
    return line.substring(quoteChar.length, line.length - quoteChar.length).trim();
  }

  const docLines: string[] = [];
  const firstLineContent = line.substring(quoteChar.length).trim();
  if (firstLineContent) docLines.push(firstLineContent);

  currentIdx++;
  while (currentIdx < lines.length) {
    const l = lines[currentIdx];
    if (l.trim().endsWith(quoteChar)) {
      const lastLineContent = l.trim().substring(0, l.trim().length - quoteChar.length).trim();
      if (lastLineContent) docLines.push(lastLineContent);
      break;
    }
    docLines.push(l.trim());
    currentIdx++;
  }

  return docLines.join('\n').trim();
}

function extractJsClassBody(content: string, classIndex: number): { body: string; endIndex: number } | null {
  const classStartIndex = content.indexOf('{', classIndex);
  if (classStartIndex === -1) return null;

  let braceCount = 1;
  let idx = classStartIndex + 1;

  while (idx < content.length && braceCount > 0) {
    const char = content[idx];
    if (char === '{') {
      braceCount++;
    } else if (char === '}') {
      braceCount--;
    }
    idx++;
  }

  if (braceCount === 0) {
    return {
      body: content.substring(classStartIndex + 1, idx - 1),
      endIndex: idx
    };
  }

  return null;
}

function splitParameters(paramText: string): string[] {
  if (!paramText.trim()) return [];
  return paramText
    .split(',')
    .map(a => a.trim().split(':')[0].trim())
    .filter(Boolean);
}

function analyzeJsTsModule(content: string): ModuleAnalysisResult {
  const classes: ClassInfo[] = [];
  const functions: FunctionInfo[] = [];
  const exports: string[] = [];

  const namedExportsRegex = /export\s+\{\s*([a-zA-Z0-9_,\s]+)\s*\}/g;
  let match: RegExpExecArray | null;
  while ((match = namedExportsRegex.exec(content)) !== null) {
    const symbols = match[1].split(',').map(s => s.trim());
    for (const sym of symbols) {
      if (sym) exports.push(sym);
    }
  }

  const classRegex = /(?:export\s+(?:default\s+)?)?class\s+([a-zA-Z0-9_]+)(?:\s+extends\s+([a-zA-Z0-9_<>\.,\s]+))?/g;
  while ((match = classRegex.exec(content)) !== null) {
    const className = match[1];
    const extendsClass = match[2]?.trim();
    const isExported = match[0].startsWith('export');
    const classIndex = match.index;

    if (isExported) {
      exports.push(className);
    }

    const jsdoc = getJsDocDescription(content, classIndex);
    const bodyInfo = extractJsClassBody(content, classIndex);

    const methods: FunctionInfo[] = [];
    const seenMethods = new Set<string>();

    if (bodyInfo) {
      const methodRegex = /(?:^|\n)\s*(?:(?:public|private|protected|static|readonly|abstract|override|async)\s+)*(?:(get|set)\s+)?([a-zA-Z0-9_]+)\s*\(([^)]*)\)\s*(?:\:\s*([^{=]+))?\s*\{/g;
      let methodMatch: RegExpExecArray | null;
      while ((methodMatch = methodRegex.exec(bodyInfo.body)) !== null) {
        const methodName = methodMatch[2];
        if (methodName === 'constructor' || seenMethods.has(methodName)) continue;
        seenMethods.add(methodName);

        methods.push({
          name: methodName,
          arguments: splitParameters(methodMatch[3]),
          returnType: methodMatch[4]?.trim(),
          description: getJsDocDescription(bodyInfo.body, methodMatch.index)
        });
      }

      const fieldArrowRegex = /(?:^|\n)\s*(?:(?:public|private|protected|static|readonly|override)\s+)*([a-zA-Z0-9_]+)\s*=\s*(?:async\s*)?\(([^)]*)\)\s*(?:\:\s*([^=;{]+))?\s*=>/g;
      let fieldMatch: RegExpExecArray | null;
      while ((fieldMatch = fieldArrowRegex.exec(bodyInfo.body)) !== null) {
        const methodName = fieldMatch[1];
        if (seenMethods.has(methodName)) continue;
        seenMethods.add(methodName);

        methods.push({
          name: methodName,
          arguments: splitParameters(fieldMatch[2]),
          returnType: fieldMatch[3]?.trim(),
          description: getJsDocDescription(bodyInfo.body, fieldMatch.index)
        });
      }
    }

    classes.push({
      name: className,
      extends: extendsClass,
      description: jsdoc,
      methods,
      isExported
    });
  }

  const funcRegex = /(?:export\s+(?:default\s+)?)?(?:async\s+)?function\s+([a-zA-Z0-9_]+)\s*\(([^)]*)\)(?:\s*:\s*([^{]+))?/g;
  while ((match = funcRegex.exec(content)) !== null) {
    const funcName = match[1];
    const isExported = match[0].startsWith('export');
    const args = splitParameters(match[2]);
    const retType = match[3]?.trim();
    const jsdoc = getJsDocDescription(content, match.index);

    if (isExported) {
      exports.push(funcName);
    }

    functions.push({
      name: funcName,
      arguments: args,
      returnType: retType,
      description: jsdoc,
      isExported
    });
  }

  const arrowRegex = /(?:export\s+)?(?:const|let|var)\s+([a-zA-Z0-9_]+)\s*(?::\s*[^=]+)?=\s*(?:async\s*)?\(([^)]*)\)\s*(?:\:\s*([^=]+))?\s*=>/g;
  while ((match = arrowRegex.exec(content)) !== null) {
    const funcName = match[1];
    const isExported = match[0].startsWith('export');
    const args = splitParameters(match[2]);
    const retType = match[3]?.trim();
    const jsdoc = getJsDocDescription(content, match.index);

    if (isExported) {
      exports.push(funcName);
    }

    functions.push({
      name: funcName,
      arguments: args,
      returnType: retType,
      description: jsdoc,
      isExported
    });
  }

  return {
    classes,
    functions,
    exports: Array.from(new Set(exports))
  };
}

function analyzePythonModule(content: string): ModuleAnalysisResult {
  const classes: ClassInfo[] = [];
  const functions: FunctionInfo[] = [];
  const exports: string[] = [];

  const lines = content.split('\n');

  const getIndent = (line: string): number => {
    const match = line.match(/^(\s*)/);
    return match ? match[1].length : 0;
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed.startsWith('class ')) {
      const classMatch = trimmed.match(/^class\s+([a-zA-Z0-9_]+)(?:\(([^)]+)\))?:/);
      if (classMatch) {
        const className = classMatch[1];
        const baseClass = classMatch[2]?.trim();
        const docstring = getPythonDocstring(lines, i);
        const classIndent = getIndent(line);

        exports.push(className);

        const methods: FunctionInfo[] = [];
        let j = i + 1;

        while (j < lines.length) {
          const nextLine = lines[j];
          const nextTrimmed = nextLine.trim();

          if (nextTrimmed === '') {
            j++;
            continue;
          }

          if (getIndent(nextLine) <= classIndent) {
            break;
          }

          if (nextTrimmed.startsWith('def ')) {
            const methodMatch = nextTrimmed.match(/^def\s+([a-zA-Z0-9_]+)\s*\(([^)]*)\)(?:\s*->\s*([^:]+))?:/);
            if (methodMatch) {
              const methodName = methodMatch[1];
              const args = splitParameters(methodMatch[2]).filter(a => a !== 'self' && a !== 'cls');
              const retType = methodMatch[3]?.trim();
              const methodDoc = getPythonDocstring(lines, j);

              methods.push({
                name: methodName,
                arguments: args,
                returnType: retType,
                description: methodDoc
              });
            }
          }

          j++;
        }

        classes.push({
          name: className,
          extends: baseClass,
          description: docstring,
          methods,
          isExported: true
        });

        i = j - 1;
      }
    } else if (trimmed.startsWith('def ')) {
      const funcMatch = trimmed.match(/^def\s+([a-zA-Z0-9_]+)\s*\(([^)]*)\)(?:\s*->\s*([^:]+))?:/);
      if (funcMatch) {
        const funcName = funcMatch[1];
        const args = splitParameters(funcMatch[2]);
        const retType = funcMatch[3]?.trim();
        const docstring = getPythonDocstring(lines, i);

        exports.push(funcName);

        functions.push({
          name: funcName,
          arguments: args,
          returnType: retType,
          description: docstring,
          isExported: true
        });
      }
    }
  }

  return {
    classes,
    functions,
    exports
  };
}

export function analyzeModule(fileContent: string, fileExtension: string): ModuleAnalysisResult {
  const ext = fileExtension.toLowerCase();

  if (ext === '.py') {
    return analyzePythonModule(fileContent);
  }

  if (['.ts', '.tsx', '.js', '.jsx'].includes(ext)) {
    return analyzeJsTsModule(fileContent);
  }

  return {
    classes: [],
    functions: [],
    exports: []
  };
}

import { FileNode } from './file-tree';
import { isReadableFile, readFileContent } from './file-reader';
import { extractDependencies, resolveDependencyPath } from './dependency';
import { analyzeModule } from './module-analyzer';
import { estimateTokens } from './token-estimator';
import { ProjectAnalysisData, FileAnalysisInfo } from './types';

/**
 * プロジェクトノードツリー全体を解析し、依存関係やモジュール構造を統合した解析データを構築します。
 */
export async function analyzeProject(
  projectName: string,
  rootNodes: FileNode[],
  folderStructureText: string
): Promise<ProjectAnalysisData> {
  // 1. すべてのファイルを平滑化（flatten）
  const allFileNodes: FileNode[] = [];
  const traverse = (nodes: FileNode[]) => {
    for (const node of nodes) {
      if (node.kind === 'file') {
        allFileNodes.push(node);
      } else if (node.children) {
        traverse(node.children);
      }
    }
  };
  traverse(rootNodes);

  // 2. 読み込み可能なテキストファイルを抽出
  const readableNodes = allFileNodes.filter(node => 
    isReadableFile(node.name, node.size || 0)
  );

  // プロジェクト内の全ファイルの相対パス一覧 (依存関係解決に利用)
  const allProjectPaths = readableNodes.map(node => node.path);

  // 3. 各ファイルの解析を非同期で実行
  const fileAnalyses: FileAnalysisInfo[] = [];
  let totalBytes = 0;
  let totalTokens = 0;

  for (const node of readableNodes) {
    try {
      const fileHandle = node.handle as FileSystemFileHandle;
      const content = await readFileContent(fileHandle);
      const dotIndex = node.name.lastIndexOf('.');
      const ext = dotIndex !== -1 ? node.name.substring(dotIndex).toLowerCase() : '';

      // 依存関係抽出
      const rawDeps = extractDependencies(content, ext);
      const resolvedDeps = rawDeps.map(depPath => 
        resolveDependencyPath(node.path, depPath, allProjectPaths)
      );

      // クラス・関数の解析
      const moduleAnalysis = analyzeModule(content, ext);

      // トークン推定
      const tokens = estimateTokens(content);

      fileAnalyses.push({
        path: node.path,
        name: node.name,
        size: node.size || 0,
        content,
        tokens,
        dependencies: resolvedDeps,
        analysis: moduleAnalysis
      });

      totalBytes += node.size || 0;
      totalTokens += tokens;
    } catch (e) {
      console.warn(`Failed to analyze file: ${node.path}`, e);
      // 読み込めなかったファイルは依存関係等なしで基本情報のみ登録
      fileAnalyses.push({
        path: node.path,
        name: node.name,
        size: node.size || 0,
        tokens: 0,
        dependencies: []
      });
    }
  }

  return {
    projectName,
    files: fileAnalyses,
    folderStructureText,
    totalBytes,
    totalTokens
  };
}

export interface ReadTimeResult {
  aiTimeSeconds: number;
  humanTimeMinutes: number;
  aiTimeFormatted: string;
  humanTimeFormatted: string;
}

/**
 * テキストの簡易トークン数を推定します。
 * 
 * 英語・半角記号（コード等）：文字数 / 3.8
 * 日本語・全角文字：文字数 * 1.3
 */
export function estimateTokens(text: string): number {
  if (!text) return 0;

  // ASCII文字 (半角英数・記号・改行・スペースなど) をマッチング
  const asciiMatch = text.match(/[\x00-\x7F]/g);
  const asciiCount = asciiMatch ? asciiMatch.length : 0;

  // 非ASCII文字 (日本語・全角記号など) の文字数
  const nonAsciiCount = text.length - asciiCount;

  // 各種比率で計算
  const asciiTokens = asciiCount / 3.8;
  const nonAsciiTokens = nonAsciiCount * 1.3;

  return Math.ceil(asciiTokens + nonAsciiTokens);
}

/**
 * 推定トークン数と文字数から、AIの想定読込時間および人間の想定読了時間を計算します。
 * 
 * AI処理想定時間：5,000 トークン/秒で処理と仮定
 * 人間読了想定時間：800 文字/分で読了と仮定
 */
export function calculateReadTime(tokenCount: number, charCount: number): ReadTimeResult {
  // AIのインジェスト想定時間 (秒)
  const aiTimeSeconds = parseFloat((tokenCount / 5000).toFixed(2));

  // 人間の読了想定時間 (分)
  const humanTimeMinutes = parseFloat((charCount / 800).toFixed(1));

  // フォーマットの作成
  const aiTimeFormatted = aiTimeSeconds < 0.1 
    ? '0.1秒未満' 
    : `${aiTimeSeconds}秒`;

  let humanTimeFormatted = '';
  if (humanTimeMinutes < 0.1) {
    humanTimeFormatted = '数秒';
  } else if (humanTimeMinutes < 1) {
    const seconds = Math.round(humanTimeMinutes * 60);
    humanTimeFormatted = `${seconds}秒`;
  } else {
    humanTimeFormatted = `${Math.ceil(humanTimeMinutes)}分`;
  }

  return {
    aiTimeSeconds,
    humanTimeMinutes,
    aiTimeFormatted,
    humanTimeFormatted
  };
}

